const money=(n,short=false)=>{const a=Math.abs(n),sign=n<0?'−':'';return sign+'$'+(short&&a>=1e6?(a/1e6).toFixed(a>=1e7?1:2)+'m':short&&a>=1000?Math.round(a/1000)+'k':Math.round(a).toLocaleString('en-US'));};
