const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',routes:'M5 6a2 2 0 1 0 0 .1 M19 18a2 2 0 1 0 0 .1 M7 6h7a4 4 0 0 1 0 8h-4a4 4 0 0 0 0 8h6',plane:'M17.8 19.2 16 11l3.5-3.5C21 6 21.5 4 21 3c-1-.5-3 0-4.5 1.5L13 8 4.8 6.2c-.5-.1-.9.1-1.1.5l-.3.5c-.2.5-.1 1 .3 1.3L9 12l-2 3H4l-1 1 3 2 2 3 1-1v-3l3-2 3.5 5.3c.3.4.8.5 1.3.3l.5-.2c.4-.3.6-.7.5-1.2z',building:'M3 21h18 M5 21V7l7-4 7 4v14 M9 9h1 M14 9h1 M9 13h1 M14 13h1 M10 21v-4h4v4',rivals:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',trophy:'M8 3h8v6a4 4 0 0 1-8 0V3ZM8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 13v7 M8 21h8',wallet:'M3 5h16v4H5a2 2 0 0 1 0-4 M3 7v12a2 2 0 0 0 2 2h16V9H5 M16 13h5v4h-5z',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c5 5 5 13 0 18-5-5-5-13 0-18',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3 M12 17h.01',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M7 17 17 7 M7 7h10v10',check:'m5 12 4 4L19 6',fuel:'M4 21V3h10v18 M4 9h10 M2 21h14 M14 7h2l3 3v7a2 2 0 0 0 4 0v-5l-4-4',chart:'M3 3v18h18 M7 14l4-4 4 3 6-8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',close:'M6 6l12 12 M18 6 6 18'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.plane}"/></svg>`;
try{const owner=JSON.parse(localStorage.getItem(OWNER)||'null');if(owner&&Date.now()-owner.time<20000)leader=false;else takeControl();}catch{}
let state=E.createGame(),loaded=false,storageError=false,offlineReport=null;
try{const raw=localStorage.getItem(STORE);if(raw){state=E.validateSave(JSON.parse(raw));loaded=true;const away=Math.min(10080,Math.max(0,(Date.now()-state.lastSave)/1000*4));if(leader&&state.started&&state.speed>0&&away>8){const before=state.cash,f=state.totals.flights,contracts=E.careerState(state).active.filter(c=>c.completedAt!==null).length,mastery=state.routes.reduce((n,r)=>n+E.routeMastery(r).level,0);E.advance(state,away);offlineReport={cash:state.cash-before,flights:state.totals.flights-f,minutes:away,contracts:E.careerState(state).active.filter(c=>c.completedAt!==null).length-contracts,mastery:state.routes.reduce((n,r)=>n+E.routeMastery(r).level,0)-mastery};}}}catch(e){storageError=true;try{const invalid=localStorage.getItem(STORE);if(invalid)localStorage.setItem(STORE+'-recovery',invalid);}catch{}}
E.initializeCareer(state);
if(['#d6ed92','#79c7b6'].includes(state.color))state.color='#4b84ff';
let interactionUntil=0;document.addEventListener('pointerdown',()=>{interactionUntil=Date.now()+800;},true);
let mapRivals=true,mapAirports=true,mapSelected=null;
let careerTab='contracts';
let noticeFilter='all',notificationPage=0;
let planeSearch='',planeStage='production',planeType='all',catalogPage=0,airportSearch='',airportStage='open',airportRegion='all',airportPage=0,routePage=0;
let view='overview',fleetTab='owned',routesTab=state.routes.length?'owned':'explore',routeOrigin=state.home,search='',rangeFilter='all',sort='distance',mapRegion='america',mapZoom=1,mapPan={x:0,y:0},dialogType='',activePlaneModalId=null,activePlaneFlying=false,geoPaths='',lastTick=Date.now(),lastRender=0,toastTimer;const navs=[['overview','overview','Overview'],['routes','routes','Route network'],['fleet','plane','Fleet & hangar'],['airports','building','Airports'],['rivals','rivals','Rival airlines'],['objectives','trophy','Career'],['finances','wallet','Finances'],['operations','settings','Operations'],['events','globe','World events'],['timeline','clock','World timeline']];
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function save(){if(!leader)return;state.lastSave=Date.now();try{localStorage.setItem(STORE,JSON.stringify(state));localStorage.setItem(OWNER,JSON.stringify({id:sessionId,time:Date.now()}));storageError=false;}catch(e){storageError=true;}const el=$('#save-status');if(el)el.textContent=storageError?'Save unavailable · export a backup':'Saved on this device';}
function dateString(){return new Date(Date.UTC(2027,0,1)+state.minute*60000).toLocaleDateString('en-US',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).toUpperCase();}
function timeString(){const min=Math.floor(state.minute%1440);return `${String(Math.floor(min/60)).padStart(2,'0')}:${String(min%60).padStart(2,'0')}`;}
function stage(){const n=state.routes.length;return n>=20?'Global airline':n>=10?'International airline':n>=3?'Regional airline':'Independent airline';}
function shell(){const ready=E.careerState(state).active.filter(c=>c.completedAt!==null).length+QUESTS.filter(q=>!state.claims.includes(q.id)&&E.questValue(state,q)>=q.target).length;document.documentElement.style.setProperty('--airline',state.color);$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><svg viewBox="0 0 32 32" aria-hidden="true"><path fill="currentColor" d="M4 26 16 4 28 26 16 20Z"/></svg><div><strong>AEROVALE</strong><small>AIRLINE EMPIRE</small></div></div><div class="airline-card"><div class="airline-mark">${esc(state.name.charAt(0).toUpperCase())}</div><div><strong>${esc(state.name)}</strong><small>${stage()}</small></div></div><div class="nav-label">YOUR AIRLINE</div><nav class="nav" aria-label="Game sections">${navs.map(([id,i,label])=>`<button data-view="${id}" class="${view===id?'active':''}" aria-current="${view===id?'page':'false'}" title="${label}">${icon(i)}<span>${label}</span>${id==='objectives'&&ready?`<span class="badge">${ready}</span>`:''}</button>`).join('')}<button class="mobile-more" data-action="nav-more">${icon('settings')}<span>More</span></button></nav><div class="sidebar-foot"><button class="ghost" data-action="help">${icon('help')}<span>Captain’s handbook</span></button><button class="ghost" data-action="settings">${icon('settings')}<span>Game & saves</span></button><div><i class="save-dot"></i><span id="save-status">${storageError?'Save unavailable':'Saved on this device'}</span></div></div></aside><main class="main"><header class="topbar"><div><div class="breadcrumb">YOUR AIRLINE / ${view==='overview'?'COMMAND CENTER':(navs.find(n=>n[0]===view)?.[2]||'Notifications').toUpperCase()}</div><h1>${({overview:'Flight deck',routes:'Route network',fleet:'Aircraft hangar',airports:'Airport portfolio',rivals:'Rival airlines',objectives:'Your airline career',finances:'Financial overview',operations:'Airline operations',events:'World events',notifications:'Notifications',timeline:'Aviation timeline'})[view]}</h1><p class="page-sub">${({overview:'Small beginnings. Extraordinary destinations.',routes:'Build connections. Find your next advantage.',fleet:'The right aircraft. The right route. Room to grow.',airports:'Earn a share from every airline passing through.',rivals:state.rivals.length+' rivals. One shared world of opportunity.',objectives:'Build something worth being proud of.',finances:'A clear view of the business you’re building.',operations:'Invest in your people, your fleet, and your future.',events:'A changing world. A new advantage.',notifications:'Every new opportunity, in one place.',timeline:'New destinations. New generations. New possibilities.'})[view]}</p></div><div class="topbar-tools"><button id="notification-bell" class="notification-bell" data-view="notifications" aria-label="Notifications, ${E.unreadNotifications(state).length} unread">${notificationBell()}</button><div class="clock"><strong id="game-date">${dateString()}</strong><br><span id="game-time">${timeString()} · DAY ${Math.floor(state.minute/1440)+1}</span></div><div class="speed" aria-label="Simulation speed">${[0,1,5,20].map(n=>`<button data-speed="${n}" class="${state.speed===n?'active':''}" title="${n===0?'Pause simulation':n+'× speed'}" aria-label="${n===0?'Pause':n+' times speed'}">${n===0?'Ⅱ':n+'×'}</button>`).join('')}</div></div></header><div id="content"></div><footer class="footer"><span>AEROVALE · <a href="credits.html" target="_blank" rel="noopener">Artwork credits</a></span><span><button class="ghost small" data-action="help">Handbook</button> <button class="ghost small" data-action="settings">Game & saves</button></span></footer></main></div>`;renderContent();}
function planeArt(m,large=false){return `<div class="aircraft-art ${large?'large':''}"><img src="assets/planes/${m.id.replace(/-g[234]$/,'')}.webp" width="600" height="400" loading="${large?'eager':'lazy'}" alt="${esc(m.name)} aircraft illustration"><span class="aircraft-gen gen-${m.generation}">${m.generation===1?'ORIGINAL AIRFRAME':m.variant+' · GEN '+m.generation}</span></div>`;}
function airportArt(a,kind='card'){return `<div class="airport-art ${kind}"><img src="${airportImage(a)}" alt="${esc(airportCredit(a).alt)}" width="800" height="450" loading="lazy"><span class="airport-art-code">${a.id}</span><span class="photo-credit">${esc(airportCredit(a).label)}</span></div>`;}
function stat(label,value,meta,i){return `<div class="stat"><div class="stat-label">${label}${icon(i)}</div><div class="stat-number">${value}</div><div class="stat-meta">${meta}</div></div>`;}
function stats(){const profit=E.dailyProfit(state);return `<div class="stats">${stat('AVAILABLE FUNDS',money(state.cash),state.debt?money(state.debt,true)+' credit outstanding':'Ready for your next move','wallet')}${stat('PROFIT / DAY',`<span class="${profit>=0?'positive':'negative'}">${profit>=0?'+':''}${money(profit)}</span>`,'Operating forecast','chart')}${stat('ACTIVE NETWORK',state.routes.length+' <small>routes</small>',E.connected(state).length+' destinations · '+state.planes.length+' aircraft','globe')}${stat('REPUTATION',Math.floor(state.reputation)+' <small>/ 100</small>','Passenger experience','star')}</div>`;}
function questHighlight(){const remaining=QUESTS.filter(q=>!state.claims.includes(q.id));const q=remaining.find(q=>E.questValue(state,q)>=q.target)||remaining.find(q=>['first_plane','first_route','first_flight'].includes(q.id))||[...remaining].sort((a,b)=>E.questValue(state,b)/b.target-E.questValue(state,a)/a.target)[0];if(!q)return `<section class="panel mission-highlight"><div class="medal">${icon('trophy')}</div><h3>Empire complete</h3><p>Every career objective earned.</p></section>`;const v=E.questValue(state,q),done=v>=q.target;return `<section class="panel mission-highlight"><div class="mission-top"><div class="medal">${icon('trophy')}</div><div><span class="eyebrow">${done?'REWARD READY':'NEXT OBJECTIVE'}</span><div class="reward-amount">${money(q.reward)}</div></div><span class="mission-count">${state.claims.length}/${QUESTS.length}</span></div><h3>${q.title}</h3><p>${q.desc}</p><div class="progress" role="progressbar" aria-valuenow="${Math.min(v,q.target)}" aria-valuemin="0" aria-valuemax="${q.target}" aria-label="${q.title}"><span style="width:${Math.min(100,v/q.target*100)}%"></span></div><button class="primary" ${done?`data-action="claim" data-id="${q.id}"`:`data-action="quest-go" data-id="${q.id}"`}>${done?'Collect reward':'Continue objective'} ${icon('arrow')}</button></section>`;}
function notificationBell(){const count=E.unreadNotifications(state).length;return `${icon('bell')}<span>Updates</span>${count?`<b class="notification-count">${count>99?'99+':count}</b>`:''}`;}
function refreshNotifications(){const button=$('#notification-bell'),unread=E.unreadNotifications(state);if(button){button.innerHTML=notificationBell();button.setAttribute('aria-label',`Notifications, ${unread.length} unread`);}if(!leader||$('#dialog').open)return;const fresh=(state.notifications||[]).filter(n=>!n.shown&&!n.read);if(fresh.length){fresh.forEach(n=>n.shown=true);toast(`${fresh.length>1?fresh.length+' new updates · ':''}${fresh[0].title}. Open Updates to read more.`);save();}}
function eventImpactLine(a,b){const es=E.activeWorldEvents(state).filter(e=>E.eventAffects(e,a,b));return es.length?`<div class="route-world-effects">${es.map(e=>`<span>${icon(E.eventDefinition(e.type).icon)}<strong>${esc(E.eventTitle(e))}</strong> · ${esc(E.eventDefinition(e.type).effect)} · Until day ${e.endDay+1}</span>`).join('')}</div>`:'';}
function worldBriefing(){const active=E.activeWorldEvents(state),upcoming=E.upcomingWorldEvents(state),entrant=E.newcomerInfo(state),e=active[0]||upcoming[0];if(!e&&entrant.status!=='announced')return '';return `<button class="world-briefing" data-view="events"><span class="briefing-icon">${icon(e?E.eventDefinition(e.type).icon:'rivals')}</span><span><small>${active.length?'LIVE WORLD EVENT':e?'ON THE HORIZON':'MARKET SHAKEUP'}</small><strong>${esc(e?E.eventTitle(e):entrant.name+' is coming')}</strong><em>${e?esc(E.eventDefinition(e.type).effect)+(active.length?' · Ends day '+(e.endDay+1):' · Begins day '+(e.startDay+1)):money(entrant.budget,true)+' launch budget · Arrives day '+(entrant.day+1)}</em></span>${icon('arrow')}</button>`;}
function worldEventCard(e){const def=E.eventDefinition(e.type),day=E.gameDay(state),active=day>=e.startDay&&day<e.endDay,over=day>=e.endDay;return `<article class="panel item-card world-event-card ${def.kind}">${airportArt(E.ap(e.airport))}<div class="card-top"><span class="eyebrow">${icon(def.icon)} ${e.scope==='global'?'WORLDWIDE':esc(e.scope==='city'?E.ap(e.airport).id:e.region)}</span><span class="tag ${def.kind==='disruption'?'amber':''}">${over?'Ended':active?'Live now':'Upcoming'}</span></div><h3>${esc(E.eventTitle(e))}</h3><p>${esc(def.description)}</p><div class="event-effect">${esc(def.effect)}</div><div class="event-dates"><span>DAY ${e.startDay+1}–${e.endDay}</span><strong>${over?'Effects expired':active?'Ends in '+hours(e.endDay*1440-state.minute):'Starts in '+hours(e.startDay*1440-state.minute)}${over?'':' of game time'}</strong></div><p class="note">${e.scope==='city'?'Flights to or from '+esc(E.ap(e.airport).city):e.scope==='region'?'Connections touching '+esc(e.region):'Every connection'}. Existing flights keep their departure forecast.</p><button class="card-action" data-action="event-explore" data-id="${e.id}">Explore ${e.scope==='city'?e.airport:e.scope==='region'?'affected airports':'routes'} ${icon('arrow')}</button></article>`;}
function worldEventsView(){const active=E.activeWorldEvents(state),upcoming=E.upcomingWorldEvents(state),entrant=E.newcomerInfo(state),season=E.event(state);return `${worldBriefing()}<div class="world-event-intro"><div><span class="eyebrow">A WORLD THAT KEEPS MOVING</span><h2>Find opportunity in the unexpected.</h2><p class="note">Travel surges, cost changes and new competition create new decisions. Announcements give you time to react; temporary effects end automatically.</p></div><button class="small" data-view="notifications">${icon('bell')} Read updates</button></div><div class="event-market"><span>${icon('globe')} BASE MARKET · ${esc(season.name)}</span><p>${esc(season.desc)} Event impacts combine with these conditions; route forecasts show the total.</p></div>${entrant.status!=='unannounced'?`<section class="entrant-banner"><div class="entrant-mark">A</div><div><span class="eyebrow">${entrant.status==='arrived'?'A NEW FORCE IN THE MARKET':'NEW AIRLINE ANNOUNCED'}</span><h2>${entrant.name}</h2><p>${money(entrant.budget,true)} launch funding · ${entrant.base} hub · ${entrant.status==='arrived'?'Now operating':'Arrives on day '+(entrant.day+1)}</p><small>Deep pockets, limited scouting. Pays for the same five licenses per connection and announces every bid.</small></div><button data-view="rivals">Watch rival plans ${icon('arrow')}</button></section>`:''}<div class="section-label"><h2>Happening now</h2><span class="eyebrow">${active.length} ACTIVE</span></div>${active.length?`<div class="card-grid">${active.map(worldEventCard).join('')}</div>`:'<div class="panel event-empty">Clear for takeoff. No special events are active right now.</div>'}<div class="section-label"><h2>Coming up</h2><span class="eyebrow">PLAN AHEAD</span></div>${upcoming.length?`<div class="card-grid">${upcoming.map(worldEventCard).join('')}</div>`:`<div class="panel event-empty">No events announced yet. The next briefing is due ${state.started&&state.worldEvents?'around day '+(state.worldEvents.nextAnnouncementDay+1):'after your airline gets flying'}. Watch Updates for announcements.</div>`}${state.worldEvents?.history.length?`<details class="explainer space-top"><summary>Recent events · ${state.worldEvents.history.length}</summary><div class="event-history">${state.worldEvents.history.slice(0,8).map(e=>`<p><strong>${esc(E.eventTitle(e))}</strong><span>Days ${e.startDay+1}–${e.endDay} · Ended</span></p>`).join('')}</div></details>`:''}<p class="note space-top">World events and release dates follow your campaign clock. Pausing stops them; offline progress can advance up to seven game days. Notifications are delivered inside the game.</p>`;}
const notificationIcon=n=>({airports:'building',aircraft:'plane',rival:'rivals',event:'globe',career:'trophy'})[n.kind];
function notificationsView(){const list=(state.notifications||[]).filter(n=>noticeFilter==='all'||noticeFilter==='unread'&&!n.read||noticeFilter===n.kind),unread=E.unreadNotifications(state).length;notificationPage=Math.min(notificationPage,Math.max(0,Math.ceil(list.length/20)-1));return `<div class="page-actions"><div><h2>Your world briefing</h2><p class="note">${unread} unread · Latest 300 updates, saved with your airline</p></div><button class="small" data-action="notifications-read-all" ${!unread?'disabled':''}>${icon('check')} Mark all read</button></div><div class="notification-filters">${[['all','All updates'],['unread','Unread'],['airports','Airports'],['aircraft','Aircraft'],['event','Events'],['rival','New rivals'],['career','Career']].map(([id,label])=>`<button class="small ${id===noticeFilter?'primary':''}" data-action="notification-filter" data-id="${id}">${label}</button>`).join('')}</div><div class="notification-list">${list.slice(notificationPage*20,notificationPage*20+20).map(n=>`<button class="notification-row panel ${n.read?'':'unread'}" data-action="notification-open" data-id="${esc(n.id)}"><span class="notification-icon">${icon(notificationIcon(n))}</span><span><small>DAY ${Math.floor(n.time/1440)+1} · ${n.kind.toUpperCase()}${n.read?'':' · NEW'}</small><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p><em>${n.items?'View all '+n.items.length+' '+(n.kind==='aircraft'?'models':'airports'):'Read briefing'} ${icon('arrow')}</em></span>${!n.read?'<i class="unread-dot" aria-label="Unread"></i>':''}</button>`).join('')||'<div class="panel empty"><h3>All quiet for now.</h3><p>New airports, aircraft, events and airline entrants will appear here as your game progresses.</p><button data-view="events">Explore world events</button></div>'}</div>${list.length>20?`<div class="pagination"><button data-action="notification-page" data-id="${notificationPage-1}" ${notificationPage===0?'disabled':''}>Previous</button><span>${notificationPage+1} / ${Math.ceil(list.length/20)}</span><button data-action="notification-page" data-id="${notificationPage+1}" ${(notificationPage+1)*20>=list.length?'disabled':''}>Next</button></div>`:''}`;}
function notificationDetail(id){const n=(state.notifications||[]).find(n=>n.id===id);if(!n)return;E.markNotificationsRead(state,id);save();renderContent();refreshNotifications();dialogType='notification';let items='';if(n.items)items=`<div class="release-list">${n.items.map(id=>{if(n.kind==='aircraft'){const m=E.model(id);return `<button class="release-item" data-action="buy-plane-detail" data-id="${id}"><img src="assets/planes/${m.id.replace(/-g[234]$/,'')}.webp" alt="${esc(m.name)}" width="96" height="64"><span><strong>${esc(m.name)}</strong><small>${m.seats} seats · ${m.speed} km/h · ${m.range.toLocaleString()} km range</small></span>${icon('arrow')}</button>`;}const a=E.ap(id);return `<button class="release-item" data-action="airport-detail" data-id="${id}"><img src="${airportImage(a)}" alt="${esc(airportCredit(a).alt)}" width="96" height="64"><span><strong>${id} · ${esc(a.city)}</strong><small>${esc(a.country)} · Now open</small></span>${icon('arrow')}</button>`;}).join('')}</div>`;openModal(esc(n.title),`<p class="note">Day ${Math.floor(n.time/1440)+1} · Saved briefing</p><p class="space-top">${esc(n.message)}</p>${items}`,`<button data-action="close">Close</button><button class="primary" data-view="${n.kind==='career'?'objectives':n.kind==='rival'?'rivals':n.kind==='event'?'events':n.kind==='aircraft'?'fleet':'airports'}">${n.kind==='career'?'Your airline career':n.kind==='rival'?'Rival airlines':n.kind==='event'?'World events':n.kind==='aircraft'?'Fleet & hangar':'Airport portfolio'}</button>`,'WORLD UPDATE');}
function exploreEvent(id){const e=[...E.activeWorldEvents(state),...E.upcomingWorldEvents(state),...(state.worldEvents?.history||[])].find(e=>e.id===id);if(!e)return;if(e.scope==='region'){airportRegion=e.region;airportStage='open';airportPage=0;airportSearch='';navigate('airports');}else{const ownsAffected=e.scope==='city'&&state.routes.some(r=>[r.a,r.b].includes(e.airport));routesTab=ownsAffected?'owned':'explore';routeOrigin=state.home;rangeFilter='all';routePage=0;search=e.scope==='city'&&(ownsAffected||e.airport!==state.home)?e.airport:'';view='routes';shell();window.scrollTo({top:0,behavior:'instant'});}}

function overview(){const world=E.nextWorldEvent(state),home=E.ap(state.home),flights=state.planes.filter(p=>p.flight);return `${stats()}${nextMove()}${worldBriefing()}<div class="flightdeck-layout"><div class="flightdeck-main">${networkPanel()}<div class="section-label"><h2>${state.planes.length?'Fleet activity':'Build your first fleet'}</h2><button class="ghost small" data-action="market">Aircraft market ${icon('arrow')}</button></div><div class="fleet-carousel">${state.planes.length?state.planes.slice(0,3).map(p=>{const m=E.model(p.model);return `<button class="fleet-preview" data-action="plane-detail" data-id="${p.id}">${planeArt(m)}<div><strong>${m.name}</strong><span>${p.flight?p.flight.route:p.schedule.length?'Ready for departure':'Awaiting a route'}</span><small>${p.id} · ${p.flight?'IN FLIGHT':'ON GROUND'}</small></div></button>`;}).join(''):PLANES.filter(p=>['atr42','q400','e175'].includes(p.id)).map(m=>`<button class="fleet-preview" data-action="buy-plane-detail" data-id="${m.id}">${planeArt(m)}<div><strong>${m.name}</strong><span>${m.seats} seats · ${num(m.range)} km</span><small>FROM ${money(E.aircraftPrice(state,m.id),true)}</small></div></button>`).join('')}</div></div><aside class="flightdeck-rail"><button class="home-airport panel" data-action="airport-detail" data-id="${state.home}">${airportArt(home,'home')}<div><span class="eyebrow">YOUR HOME BASE</span><h3>${home.city}</h3><span>${home.id} · ${home.country}</span></div></button>${questHighlight()}<section class="panel world-progress"><div class="panel-heading"><h2>A growing world</h2>${icon('globe')}</div><div class="world-progress-body"><div><strong>${world.airports}<small> / 600</small></strong><span>airports open</span></div><div><strong>${world.aircraft}<small> / 400</small></strong><span>models introduced</span></div></div><button class="card-action" data-view="timeline">See what opens next ${icon('arrow')}</button></section></aside></div>${state.cash<25000&&!state.bailout?'<div class="welcome-strip"><h3>A fresh start for your airline</h3><button data-action="rescue">Claim $125,000 recovery grant</button></div>':''}<div class="section-label"><h2>Airline dispatch</h2><span class="eyebrow">WORLD UPDATES</span></div><div class="dispatch-grid">${state.log.slice(0,3).map(l=>`<article class="panel dispatch"><div class="dispatch-icon">${icon(l.type==='flight'?'plane':l.type==='airport'?'building':'bell')}</div><div><span class="eyebrow">DAY ${Math.floor(l.time/1440)+1} · ${l.type}</span><p>${esc(l.text)}</p></div></article>`).join('')}</div>`;}
function networkPanel(full=false){return `<section class="panel network ${full?'full-network':''}"><div class="network-head"><div><span class="eyebrow">AIRLINE OPERATIONS</span><h2>${full?'Explore the world':'Your live network'}</h2></div><span class="network-status">${state.planes.filter(p=>p.flight).length} AIRBORNE <i></i></span></div><div class="map-wrap" id="network-map"></div><div class="network-foot"><span>${icon('globe')} <strong>${state.routes.length}</strong> routes · <strong>${E.openAirports(state).length}</strong> open airports</span><button class="small" data-action="map-fit">${icon('routes')} Fit network</button></div></section>`;}
const routePlaneChoices=new Map();
const ownedAircraftFor=(a,b)=>state.planes.find(p=>E.model(p.model).range>=E.distance(a,b));

function routeAssignmentControls(r,scope='card'){
 const assigned=state.planes.filter(p=>p.schedule.includes(r.id)),capacity=E.routeLicenseCount(r);
 const assignedCards=assigned.map(plane=>{const assigned=plane;
 const m=E.model(assigned.model);return `<div class="route-assignment assigned-route"><img src="assets/planes/${m.id.replace(/-g[234]$/,'')}.webp" alt="${esc(m.name)}" loading="lazy"><div><span class="eyebrow">ASSIGNED AIRCRAFT</span><strong>${assigned.id} · ${esc(m.name)}</strong><small>${assigned.flight?'In flight':assigned.repair?'Maintenance':assigned.auto?'Automatic departures on':'Departures paused'}</small></div><button class="small" data-action="plane-detail" data-id="${assigned.id}">Manage aircraft</button></div>`;}).join('');
 if(assigned.length>=capacity)return assignedCards;
 const choices=state.planes.filter(p=>!p.schedule.includes(r.id)).map(p=>{try{return {p,plan:E.routeAssignment(state,r.id,p.id)};}catch(e){return {p,reason:p.flight?'In flight':E.distance(r.a,r.b)>E.model(p.model).range?'Out of range':p.schedule.length>=6?'Rotation full':e.message.includes('share one base')?'Different rotation base':e.message.includes('funds')?'Ferry cost exceeds funds':e.message};}}).sort((a,b)=>Number(!a.plan)-Number(!b.plan)||a.p.schedule.length-b.p.schedule.length);
 const chosen=choices.find(c=>c.p.id===routePlaneChoices.get(r.id))||choices.find(c=>c.plan),selectId=`assign-${scope}-${r.id}`;
 if(chosen)routePlaneChoices.set(r.id,chosen.p.id);
 const detail=chosen?.plan?`${chosen.p.schedule.length?'Adds to its '+chosen.p.schedule.length+'-route rotation.':'Starts an automatic round-trip rotation.'} ${chosen.plan.relocation?'Ferry cost: '+money(chosen.plan.relocation)+'.':''}${chosen.p.repair?' Departs after maintenance.':''}`:chosen?'Unavailable: '+chosen.reason+'.'+(chosen.p.flight?' Pause departures and wait for this round trip to land.':''):choices.length?'No compatible aircraft available. Check range and rotation limits.':'Buy or lease an aircraft to start flying this route.';
 return `<div class="route-assignment-group">${assignedCards}<div class="route-assignment" data-assignment-route="${r.id}" data-assignment-scope="${scope}"><label for="${selectId}">${icon('plane')} ${assigned.length?'Assign another aircraft':'Assign an aircraft'} <span class="note">· ${capacity-assigned.length} slot${capacity-assigned.length===1?'':'s'} free</span></label>${choices.length?`<select id="${selectId}" data-route-plane="${r.id}" aria-describedby="${selectId}-hint" ${!choices.some(c=>c.plan)?'disabled':''}>${!chosen?'<option value="">No available aircraft</option>':''}${choices.map(c=>`<option value="${c.p.id}" ${c.p.id===chosen?.p.id?'selected':''} ${!c.plan?'disabled':''}>${c.p.id} · ${esc(E.model(c.p.model).name)} · ${c.reason||(!c.p.schedule.length?'Ready to assign':c.p.schedule.length+' routes')}${c.plan?.relocation?' · ferry '+money(c.plan.relocation,true):''}</option>`).join('')}</select><button class="primary" data-action="assign-route" data-id="${r.id}" ${!chosen?.plan?'disabled':''}>${icon('plane')} Assign &amp; fly</button>`:'<button class="primary" data-action="market">Find an aircraft</button>'}<p class="note" id="${selectId}-hint">${esc(detail)}</p></div></div>`;
}


function routeSupply(a,b){const id=E.key(a,b),owned=state.routes.find(r=>r.id===id),mine=owned?E.routeLicenseCount(owned):0,rivals=state.rivals.flatMap(ai=>ai.routes.filter(r=>r.id===id).map(()=>({name:ai.name,you:false}))),holders=[...Array.from({length:mine},()=>({name:state.name,you:true})),...rivals],left=E.remainingLicenses(state,a,b);return `<div class="route-supply"><div><span>Route licenses</span><strong class="${left?'':'negative'}">${left?left+' of '+E.ROUTE_LICENSE_LIMIT+' available':'Sold out · 0 of '+E.ROUTE_LICENSE_LIMIT}</strong></div><div class="license-slots" role="img" aria-label="${mine} yours, ${rivals.length} held by rivals, ${left} available">${Array.from({length:E.ROUTE_LICENSE_LIMIT},(_,i)=>`<span class="${holders[i]?holders[i].you?'yours':'claimed':'available'}" title="${esc(holders[i]?.name||'Available')}">${icon(holders[i]?'plane':'check')}</span>`).join('')}</div><p>${mine} yours · ${rivals.length} held by rivals · ${left} available</p>${mine?'<p>One aircraft per license. Each license stays yours permanently.</p>':''}</div>`;}

function routeCard(a,b,owned){const id=E.key(a,b),r=owned||{a,b,fare:1},p=ownedAircraftFor(a,b)||{model:E.releasedPlanes(state).find(p=>p.range>=E.distance(a,b))?.id||'a359'},e=E.economics(state,r,p),used=E.slots(state,a,b),assigned=state.planes.find(p=>p.schedule.includes(id)),threat=E.rivalPlans(state).find(b=>E.key(b.a,b.b)===id);return `<article class="panel item-card route-card">${airportArt(E.ap(b))}<div class="card-top"><span class="eyebrow">${E.ap(b).region}</span><span class="tag ${used>=E.ROUTE_LICENSE_LIMIT||threat?'amber':owned?'':'muted-tag'}">${owned?assigned?'Operating':'Unassigned':used>=E.ROUTE_LICENSE_LIMIT?'Sold out':`${E.remainingLicenses(state,a,b)} of ${E.ROUTE_LICENSE_LIMIT} available`}</span></div><div class="route-codes">${a}<span>↔</span>${b}</div><p>${esc(E.ap(a).city)} to ${esc(E.ap(b).city)}</p><div class="data-grid"><div><small>Distance</small><strong>${num(e.km)} km</strong></div><div><small>Daily passenger demand</small><strong>${num(E.routeDemand(state,a,b))}</strong></div><div><small>Est. round-trip profit</small><strong class="${e.profit>=0?'positive':'negative'}">${money(e.profit)}</strong></div><div><small>${owned?'Lifetime revenue':'License price'}</small><strong>${money(owned?owned.revenue:E.licensePrice(a,b),true)}</strong></div></div>${owned?masteryStrip(owned):''}${routeSupply(a,b)}${eventImpactLine(a,b)}<p class="mini-stat">Forecast with ${E.model(p.model).name} · ${pct(e.load)} seats filled</p>${owned?routeAssignmentControls(owned):''}${owned&&E.remainingLicenses(state,a,b)?`<button class="small extra-license" data-action="buy-route" data-a="${a}" data-b="${b}" ${state.cash<E.licensePrice(a,b)?'disabled':''}>Buy another license · ${money(E.licensePrice(a,b),true)}</button>`:''}${threat?`<div class="hint">${state.rivals.find(x=>x.id===threat.rival).name} is targeting this route.</div>`:''}<button class="card-action ${owned?'':'primary'}" data-action="route-detail" data-a="${a}" data-b="${b}">${owned?'Manage route':used>=E.ROUTE_LICENSE_LIMIT?'View sold-out route':'Explore route'} ${icon('arrow')}</button></article>`;}
function routes(){let list;if(routesTab==='owned')list=state.routes.filter(r=>(r.a+' '+r.b+' '+E.ap(r.a).city+' '+E.ap(r.b).city).toLowerCase().includes(search.toLowerCase()));else list=E.openAirports(state).filter(a=>a.id!==routeOrigin&&!state.routes.some(r=>r.id===E.key(routeOrigin,a.id))&&(a.city+' '+a.id+' '+a.country).toLowerCase().includes(search.toLowerCase())&&(rangeFilter!=='fleet'||ownedAircraftFor(routeOrigin,a.id))).map(a=>({a:routeOrigin,b:a.id}));list.sort((a,b)=>sort==='cost'?E.licensePrice(a.a,a.b)-E.licensePrice(b.a,b.b):sort==='demand'?E.routeDemand(state,b.a,b.b)-E.routeDemand(state,a.a,a.b):E.distance(a.a,a.b)-E.distance(b.a,b.b));return `${networkPanel(true)}<div class="section-label"><h2>${routesTab==='owned'?'Your connections':'Find your next destination'}</h2><span class="note">Tap an airport on the map to plan a route.</span></div><div class="page-actions"><div class="tab-row"><button class="${routesTab==='owned'?'active':''}" data-route-tab="owned">Your routes · ${state.routes.length}</button><button class="${routesTab==='explore'?'active':''}" data-route-tab="explore">Explore routes</button></div><span class="chip">${money(state.cash,true)} available</span></div><div class="search-row">${routesTab==='explore'?`<select aria-label="Origin airport" id="route-origin">${E.connected(state).map(id=>`<option value="${id}" ${id===routeOrigin?'selected':''}>From ${id} · ${E.ap(id).city}</option>`).join('')}</select>`:''}<input id="route-search" aria-label="Search routes" placeholder="Search city or airport…" value="${esc(search)}"><select id="route-sort" aria-label="Sort routes"><option value="distance" ${sort==='distance'?'selected':''}>Shortest distance</option><option value="cost" ${sort==='cost'?'selected':''}>Lowest license cost</option><option value="demand" ${sort==='demand'?'selected':''}>Highest demand</option></select>${routesTab==='explore'?`<select id="range-filter" aria-label="Range filter"><option value="all">All destinations</option><option value="fleet" ${rangeFilter==='fleet'?'selected':''}>Within fleet range</option></select>`:''}</div>${routesTab==='explore'?`<details class="explainer"><summary>How route licenses work</summary><p>Each connection has ${E.ROUTE_LICENSE_LIMIT} permanent licenses shared by all airlines. An airline can own several licenses; each supports one aircraft. Both directions use the same pool. Once all licenses are owned, the connection is sold out. Existing owners keep their routes; there are no buyouts or extra licenses.</p></details>`:''}<div class="card-grid">${list.slice(routePage*24,routePage*24+24).map(r=>routeCard(r.a,r.b,routesTab==='owned'?r:null)).join('')}</div>${pager('routes',routePage,list.length)}${!list.length?`<div class="panel empty">${icon('routes')}<h2>${routesTab==='owned'?'Your network starts here.':'No routes match your filters.'}</h2><p>${routesTab==='owned'?'Explore the route market to find your first connection. Salt Lake City to Denver is a good regional starting point.':'Try another origin or clear your search.'}</p><button class="primary" data-route-tab="explore">Explore route opportunities</button></div>`:''}`;}
function planeCard(p){const m=E.model(p.model),rs=E.rotationStats(state,p),status=p.flight?'In flight':p.repair?'Maintenance':p.schedule.length?p.auto?'Boarding':'Paused':'Ready to assign';return `<article class="panel item-card owned-plane">${planeArt(m)}<div class="card-top"><span class="eyebrow">${p.id} · ${p.base} BASE</span><span class="tag ${!p.schedule.length?'amber':''}">${status}</span></div><h3>${m.name}</h3><p>${m.type} · ${p.leased?'Leased':'Owned'}</p><div class="data-grid"><div><small>Daily profit forecast</small><strong class="${rs.daily<0?'negative':'positive'}">${money(rs.daily)}</strong></div><div><small>Aircraft condition</small><strong>${Math.round(p.condition)}%</strong></div><div><small>Completed flights</small><strong>${num(p.flights)}</strong></div><div><small>Maximum range</small><strong>${num(m.range)} km</strong></div></div>${p.flight?`<div class="note">${p.flight.route} · ${hours(Math.max(0,p.flight.duration-p.progress))} until return</div><div class="progress"><span style="width:${Math.min(100,p.progress/p.flight.duration*100)}%"></span></div>`:`<div class="note">${p.schedule.length?p.schedule.join(' → '):'No rotation scheduled. Give this aircraft a route.'}</div>`}<button class="card-action" data-action="plane-detail" data-id="${p.id}">Manage aircraft ${icon('arrow')}</button></article>`;}
function aircraftCard(m){const status=E.modelStatus(state,m),available=status!=='upcoming'&&state.routes.length>=m.unlock,price=E.aircraftPrice(state,m.id);return `<article class="panel item-card aircraft-card">${planeArt(m)}<div class="card-top"><span class="eyebrow">GEN ${m.generation} · ${m.variant}</span><span class="tag ${status==='legacy'?'amber':status==='upcoming'?'muted-tag':''}">${status==='upcoming'?'Day '+(m.releaseDay+1):status==='legacy'?'Legacy · 45% off':'In production'}</span></div><h3>${esc(m.name)}</h3><p>${m.type}${m.fictionalVariant?' · game variant':''}</p><div class="data-grid"><div><small>Passengers</small><strong>${m.seats} seats</strong></div><div><small>Cruise speed</small><strong>${num(m.speed)} km/h</strong></div><div><small>Maximum range</small><strong>${num(m.range)} km</strong></div><div><small>Fuel / 100 seat-km</small><strong>${(m.burn/m.seats*100).toFixed(2)} units</strong></div></div><div class="divider"></div><div class="metric-pair"><span class="muted">${status==='legacy'?'Used purchase':'Purchase price'}</span><strong class="mono">${money(price,true)}</strong></div><button class="card-action ${available?'primary':''}" data-action="buy-plane-detail" data-id="${m.id}">${status==='upcoming'?'Preview future model':available?'View aircraft':m.unlock+' routes to unlock'} ${icon('arrow')}</button></article>`;}
function pager(kind,page,total){const pages=Math.ceil(total/24);if(pages<2)return '';return `<div class="pagination"><button data-action="page" data-kind="${kind}" data-page="${page-1}" ${page===0?'disabled':''}>Previous</button><span>${page*24+1}–${Math.min(total,(page+1)*24)} of ${total}</span><button data-action="page" data-kind="${kind}" data-page="${page+1}" ${page>=pages-1?'disabled':''}>Next</button></div>`;}
function fleet(){let catalog=PLANES.filter(m=>(planeStage==='all'?E.modelStatus(state,m)!=='upcoming':E.modelStatus(state,m)===planeStage)&&(planeType==='all'||(planeType==='regional'?m.seats<125:planeType==='narrow'?m.seats>=125&&m.seats<245:m.seats>=245))&&(m.name+' '+m.type).toLowerCase().includes(planeSearch.toLowerCase())).sort((a,b)=>a.releaseDay-b.releaseDay||a.price-b.price);return `<div class="page-actions"><div class="tab-row"><button class="${fleetTab==='owned'?'active':''}" data-fleet-tab="owned">Your fleet · ${state.planes.length}</button><button class="${fleetTab==='market'?'active':''}" data-fleet-tab="market">Aircraft market</button></div><span class="chip">${money(state.cash,true)} available</span></div>${fleetTab==='owned'?state.planes.length?`<div class="card-grid">${state.planes.map(planeCard).join('')}</div>`:`<section class="panel"><div class="fleet-feature" style="height:250px"><div class="eyebrow">YOUR FIRST CHAPTER</div><h3>A great airline starts small.</h3><p>Start with an efficient ATR 42, or lease an aircraft and keep more cash for your first routes.</p><button class="primary" data-fleet-tab="market">Find your first aircraft ${icon('arrow')}</button></div></section>`:`<div class="world-strip"><span><strong>${E.releasedPlanes(state).length} / 400</strong> models and variants introduced · 100 airframe families</span><button class="ghost small" data-view="timeline">Release calendar ${icon('arrow')}</button></div><div class="search-row"><input id="plane-search" value="${esc(planeSearch)}" placeholder="Search aircraft or manufacturer…" aria-label="Search aircraft"><select id="plane-stage" aria-label="Aircraft market lifecycle">${[['production','In production'],['legacy','Legacy & used'],['upcoming','Upcoming releases'],['all','All introduced models']].map(([v,n])=>`<option value="${v}" ${v===planeStage?'selected':''}>${n}</option>`).join('')}</select><select id="plane-type" aria-label="Aircraft size">${[['all','All aircraft sizes'],['regional','Regional · under 125 seats'],['narrow','Medium · 125–244 seats'],['wide','Large · 245+ seats']].map(([v,n])=>`<option value="${v}" ${v===planeType?'selected':''}>${n}</option>`).join('')}</select></div><details class="explainer"><summary>Aircraft generations &amp; the used market</summary><p>New airframes arrive every 8 game days. Later Eco, Express and Stretch generations are fictional technology variants with different performance. Older aircraft stay flyable and become cheaper used purchases. Artwork depicts each base airframe.</p></details><div class="card-grid">${catalog.slice(catalogPage*24,catalogPage*24+24).map(aircraftCard).join('')}</div>${pager('planes',catalogPage,catalog.length)}${!catalog.length?'<div class="panel empty"><h3>No aircraft in this view yet.</h3><p>Change your filters or explore the upcoming release calendar.</p></div>':''}`}`;}

function airports(){let airports=AIRPORTS.filter(a=>(airportStage==='all'||airportStage==='owned'&&state.airports.includes(a.id)||airportStage==='open'&&E.airportOpen(state,a.id)||airportStage==='upcoming'&&!E.airportOpen(state,a.id))&&(airportRegion==='all'||a.region===airportRegion)&&(a.id+' '+a.city+' '+a.country).toLowerCase().includes(airportSearch.toLowerCase())).sort((a,b)=>Number(state.airports.includes(b.id))-Number(state.airports.includes(a.id))||Number(E.connected(state).includes(b.id))-Number(E.connected(state).includes(a.id))||a.opensDay-b.opensDay||a.price-b.price);return `<div class="stats">${stat('Airports owned',state.airports.length,'Build a portfolio across your network','building')}${stat('Airports now open',E.openAirports(state).length+' / 600','20 new airports every 10 game days','globe')}${stat('Daily airport income',money(state.airports.reduce((n,id)=>n+E.airportDaily(state,id),0)),'Traffic from all airlines · individual airport upgrades','wallet')}${stat('Total income earned',money(state.totals.airport),'Collected automatically over time','chart')}</div><div class="search-row"><input id="airport-search" placeholder="Search city, country or code…" value="${esc(airportSearch)}" aria-label="Search airports"><select id="airport-stage" aria-label="Airport availability">${[['open','Open airports'],['upcoming','Opening soon'],['owned','Your airports'],['all','Complete world · 600 airports']].map(([v,n])=>`<option value="${v}" ${v===airportStage?'selected':''}>${n}</option>`).join('')}</select><select id="airport-region" aria-label="Airport continent"><option value="all">All continents</option>${['North America','South America','Europe','Africa','Asia','Oceania'].map(r=>`<option ${airportRegion===r?'selected':''}>${r}</option>`).join('')}</select></div><details class="explainer"><summary>How airport ownership earns money</summary><p>Connect an airport to unlock ownership. Upgrade each airport’s terminals, retail district and ground services through three levels each. Base revenue share is ${sharePercent(E.airportShare(state))}; retail development adds up to 1.5 percentage points at that airport. 20 new airports open every 10 game days.</p></details><div class="card-grid">${airports.slice(airportPage*24,airportPage*24+24).map(a=>{const owned=state.airports.includes(a.id),open=E.airportOpen(state,a.id),reachable=E.connected(state).includes(a.id);return `<article class="panel item-card airport-card">${airportArt(a)}<div class="card-top"><div class="airport-code">${a.id}</div><span class="tag ${owned?'':!open?'muted-tag':reachable?'amber':'muted-tag'}">${owned?'Your airport':!open?'Opens day '+(a.opensDay+1):reachable?'Available':'Connect to unlock'}</span></div><h3>${esc(a.city)}</h3><p>${esc(a.country)} · ${a.region}</p><div class="data-grid"><div><small>${owned?'Asset value':'Purchase price'}</small><strong>${money(owned?E.airportAssetValue(state,a.id):a.price,true)}</strong></div><div><small>Daily income forecast</small><strong class="positive">${money(E.airportDaily(state,a.id))}</strong></div></div>${owned?airportDevelopmentBadge(a.id):''}<button class="card-action ${reachable&&!owned?'primary':''}" data-action="airport-detail" data-id="${a.id}">${owned?'Manage & upgrade':!open?'Preview airport':'Explore acquisition'} ${icon('arrow')}</button></article>`}).join('')}</div>${pager('airports',airportPage,airports.length)}${!airports.length?'<div class="panel empty"><h3>No airports match this view.</h3><p>Try another filter or explore the complete world.</p></div>':''}`;}
function timeline(){const day=E.gameDay(state),world=E.nextWorldEvent(state),days=[...new Set([...AIRPORTS.map(a=>a.opensDay),...PLANES.map(p=>p.releaseDay)])].filter(d=>d>day).sort((a,b)=>a-b);return `<div class="stats">${stat('Campaign day',num(day+1),'The world evolves on the game calendar','clock')}${stat('Open airports',world.airports+' / 600','20 new destinations every 10 days','globe')}${stat('Aircraft introduced',world.aircraft+' / 400','100 families · 4 technology generations','plane')}${stat('Current generation','GEN '+Math.min(4,Math.floor(day/60)+1),'A new technology generation every 60 days','star')}</div><div class="two-col section-gap"><section class="panel panel-body"><span class="eyebrow">AIRCRAFT EVOLUTION</span><h2 style="margin-top:12px">The fleet you build today isn’t the fleet you’ll fly forever.</h2><p class="note space-top">Original models establish your network. Eco derivatives reduce fuel burn. Express derivatives shorten journeys. Stretch derivatives add capacity. Newer generations cost more, so the best replacement depends on route demand and operating costs.</p><p class="note space-top">After 100 days on the market, earlier models leave production and enter the used market at a 45% discount. Owned aircraft keep flying, but aging increases maintenance costs and reduces resale value. Trade-ins keep your routes and rotation intact.</p></section><section class="panel panel-body"><span class="eyebrow">A GROWING WORLD</span><h2 style="margin-top:12px">New airports. A fresh race.</h2><p class="note space-top">600 real locations across more than 130 countries. Airport access opens in groups of 20; every new destination creates opportunities for you and your rivals. Opening dates are fictional campaign milestones, not historical dates.</p><div class="divider"></div><p class="note">At 20× speed, ten game days take about three real minutes. The complete catalog is introduced by day 285. Offline progress follows the same timeline, up to seven game days per visit.</p><div class="space-top"><button data-view="airports">Explore future airports</button> <button data-action="future-planes">Preview future aircraft</button></div></section></div><div class="panel"><div class="panel-heading"><h2>${days.length?'On the horizon':'Every horizon is open.'}</h2><span class="eyebrow">NEXT ${Math.min(12,days.length)} MILESTONES</span></div><div class="timeline-list">${days.slice(0,12).map(d=>{const a=AIRPORTS.filter(a=>a.opensDay===d),ps=PLANES.filter(p=>p.releaseDay===d);return `<article class="timeline-item"><div class="timeline-day"><small>DAY</small><strong>${d+1}</strong></div><div><h3>${[a.length?a.length+' airports opening':'',ps.length?ps.length+' aircraft introductions':''].filter(Boolean).join(' · ')}</h3>${a.length?`<p>${a.slice(0,5).map(x=>esc(x.city)+' ('+x.id+')').join(', ')}${a.length>5?'…':''}</p>`:''}${ps.length?`<p>${ps.slice(0,3).map(x=>esc(x.name)).join(', ')}${ps.length>3?'…':''}</p>`:''}<span class="note">In ${d-day} game days</span></div></article>`}).join('')||'<div class="panel-body"><p class="note">All 600 airports and 400 aircraft models and variants are introduced. Keep optimizing your empire.</p></div>'}</div></div>`;}

function rivalActivity(ai){
 const bid=E.rivalPlans(state).find(b=>b.rival===ai.id),delay=Math.max(0,(bid?.at??ai.nextExpansionAt??state.minute)-state.minute),remaining=hours(delay),label=bid?'Expansion planned':!state.started?'Awaiting your first aircraft':ai.expansionStatus==='capacity'?'Network at current limit':ai.expansionStatus==='watching'?'Watching for an investment':'Scouting new routes';
 const detail=bid?`${bid.a}–${bid.b} · Purchase in ${remaining} (game time)`:!state.started?'Buy your first aircraft to start the world.':ai.nextExpansionAt===undefined?'Scouting resumes when game time advances.':ai.expansionStatus==='watching'?`No suitable investment last check. Reviews again in ${remaining} (game time).`:ai.expansionStatus==='capacity'?`Reviews capacity in ${remaining} (game time).`:`Next market review in ${remaining} (game time).`;
 return `<div class="rival-activity ${bid?'planned':''}"><span class="eyebrow">${icon(bid?'routes':'clock')}${label}</span><strong>${detail}</strong>${bid?`<p>${esc(bid.strategy||'Evaluating this connection')}.</p><button class="small" data-action="route-detail" data-a="${bid.a}" data-b="${bid.b}">Inspect planned route ${icon('arrow')}</button>`:''}</div>`;
}
function rivals(){const plans=E.rivalPlans(state),leaders=[{name:state.name,cash:state.cash,worth:E.netWorth(state),routes:E.airlineLicenses(state),you:true,color:state.color},...state.rivals.map(r=>({name:r.name,cash:r.cash,worth:r.cash+r.routes.reduce((n,x)=>n+E.licensePrice(x.a,x.b),0)+r.routes.reduce((n,t)=>n+E.model(t.model).price*(t.leased?.14:.7),0),routes:r.routes.length,color:r.color}))].sort((a,b)=>b.worth-a.worth);return `${plans.length?`<div class="notice"><strong>${plans.length} airline${plans.length===1?' is':'s are'} planning expansion.</strong> Each rival runs its own schedule. See their targets and countdowns below.</div>`:''}${state.speed===0?'<div class="notice">Simulation paused. Rival purchases resume when you restart time.</div>':''}<div class="two-col"><section class="panel"><div class="panel-heading"><h2>The airline league</h2><span class="eyebrow">ESTIMATED VALUE</span></div><div class="table-wrap"><table><thead><tr><th>Rank / airline</th><th>Licenses</th><th>Enterprise value</th></tr></thead><tbody>${leaders.map((l,i)=>`<tr><td><span style="color:${l.color}">${i+1}. ${esc(l.name)}</span>${l.you?'<small>Your airline</small>':''}</td><td>${l.routes}</td><td class="mono">${money(l.worth,true)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel panel-body"><h2>A living, competitive world.</h2><p class="note space-top">Rivals earn money from their flights, scout valuable connections, and spend their own cash on new licenses. They compare net profit after aircraft costs and competition, keep a cash reserve, and strengthen profitable hubs. They may buy more licenses on a successful connection when the extra capacity still pays. Each airline scouts independently, favors different opportunities, and announces purchases 12–48 game hours ahead. Their own investment cycles usually produce a new license every 2–5 game days when profitable routes are affordable. Repeat purchases are spaced out, giving you time to react.</p><div class="divider"></div><p class="note">Airlines can buy multiple licenses from the same pool of ${E.ROUTE_LICENSE_LIMIT} per connection. Competition reduces the passengers available to each carrier. A rival can never take a route you already own.</p><div class="divider"></div><p class="note">Every connection has a fixed supply. Once all ${E.ROUTE_LICENSE_LIMIT} licenses are owned, nobody can buy another. Watch rival plans and secure the connections you want before they sell out.</p></section></div><div class="card-grid space-top">${state.rivals.map(r=>`<article class="panel item-card"><div class="card-top"><div class="rival-symbol" style="color:${r.color}">${r.initial}</div><span class="eyebrow">${r.base} BASE</span></div><h3>${r.name}</h3><p>${E.aiStrategy(r).label}</p><p class="note">${E.aiStrategy(r).description}</p><div class="data-grid"><div><small>Cash reserves</small><strong>${money(r.cash,true)}</strong></div><div><small>Route licenses</small><strong>${r.routes.length}</strong></div></div>${rivalActivity(r)}<div class="note">${r.routes.slice(-5).map(t=>t.id).join(' · ')}</div></article>`).join('')}</div>`;}
function milestonesView(){const claimed=state.claims.length;return `<div class="welcome-strip"><div><h3>Your airline’s story, one milestone at a time.</h3><p>${claimed} of ${QUESTS.length} objectives complete · ${money(state.totals.rewards)} in rewards earned</p></div><span class="chip">${Math.round(claimed/QUESTS.length*100)}% complete</span></div><div class="two-col">${QUESTS.map((q,i)=>{const v=E.questValue(state,q),done=v>=q.target,claimed=state.claims.includes(q.id);return `<article class="panel quest-card ${claimed?'claimed':''}"><div class="quest-icon">${icon(claimed?'check':'trophy')}</div><div class="quest-main"><div class="quest-top"><h3>${q.title}</h3><strong>${money(q.reward,true)}</strong></div><p>${q.desc}</p><div class="progress"><span style="width:${Math.min(100,v/q.target*100)}%"></span></div><div class="quest-bottom"><span>${claimed?'Completed':num(Math.min(v,q.target))+' / '+num(q.target)}</span><button class="small ${done&&!claimed?'primary':''}" ${claimed?'disabled':done?`data-action="claim" data-id="${q.id}"`:`data-action="quest-go" data-id="${q.id}"`}>${claimed?'Reward claimed':done?'Claim reward':'View next step'}</button></div></div></article>`}).join('')}</div>`;}
function finances(){const t=state.totals,totalcost=t.fuel+t.crew+t.maintenance+t.fees+t.interest+t.leases;return `${stats()}<div class="two-col"><section class="panel panel-body"><span class="eyebrow">LIFETIME OPERATING RESULTS</span><h2 style="margin-top:10px">The business behind the wings.</h2>${[['Passenger revenue',t.revenue],['Airport ownership income',t.airport],['Fuel',-t.fuel],['Crew & ground handling',-t.crew],['Maintenance reserve & service',-t.maintenance],['Airport fees',-t.fees],['Aircraft leases',-t.leases],['Credit interest',-t.interest]].map(([k,v])=>`<div class="ledger-row"><span class="muted">${k}</span><span class="mono ${v>=0?'positive':''}">${money(v)}</span></div>`).join('')}<div class="ledger-row"><strong>Net operating income</strong><strong class="mono positive">${money(t.revenue+t.airport-totalcost)}</strong></div><p class="note" style="margin-top:15px">Aircraft, route and airport purchases are investments, shown in the transaction history. Objective rewards are separate from operating income.</p></section><section class="panel panel-body"><span class="eyebrow">YOUR AIRLINE’S VALUE</span><div class="money-large">${money(E.netWorth(state))}</div><p class="note">Cash + owned aircraft resale value + route resale value + airports − outstanding debt.</p>${chart()}<div class="divider"></div><h3>Business credit</h3><div class="metric-pair"><span class="muted">Outstanding balance</span><strong class="mono">${money(state.debt)}</strong></div><p class="note">Interest: 0.2% per game day. Credit limit: ${money(Math.max(150000,Math.min(5000000,E.netWorth(state)*.5)),true)}. Borrowing can speed up growth, but interest reduces profit.</p><div style="display:flex;gap:10px;margin-top:18px"><button data-action="credit">Manage credit</button><button data-action="export">Export save</button></div></section></div><section class="panel space-top"><div class="panel-heading"><h2>Recent transactions</h2><span class="eyebrow">LATEST 30</span></div><div class="table-wrap"><table><thead><tr><th>Day</th><th>Description</th><th>Category</th><th>Cash movement</th></tr></thead><tbody>${state.ledger.slice(0,30).map(l=>`<tr><td>${Math.floor(l.time/1440)+1}</td><td>${esc(l.label)}</td><td class="muted">${esc(l.category)}</td><td class="mono ${l.amount>=0?'positive':''}">${l.amount>0?'+':''}${money(l.amount)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">Your first investment will appear here.</td></tr>'}</tbody></table></div><p class="note" style="padding:16px 22px">Flight transactions show net cash after costs. Airport income, lease rent and interest accrue continuously and are totaled above.</p></section>`;}
function chart(){const h=state.history;const vals=h.map(x=>x.worth),min=Math.min(0,...vals),max=Math.max(500000,...vals),pts=h.map((x,i)=>`${30+i/Math.max(1,h.length-1)*460},${125-(x.worth-min)/(max-min)*105}`).join(' ');return `<svg class="spark-chart" viewBox="0 0 530 155" role="img" aria-label="Net worth over the last ${h.length} game days"><path d="M30 25H500 M30 75H500 M30 125H500" stroke="#33463d" fill="none"/><polyline points="${pts}" stroke="${state.color}" stroke-width="2.5" fill="none"/>${h.length===1?'<circle cx="30" cy="20" r="4" fill="var(--lime)"/>':''}<text x="30" y="149">DAY ${h[0].day+1}</text><text x="434" y="149">DAY ${h.at(-1).day+1}</text></svg>`;}
function operations(){return `<div class="two-col section-gap"><section class="panel panel-body"><span class="eyebrow">AUTOMATION, BUILT IN</span><h2 style="margin:14px 0">Your airline works while you’re away.</h2><p class="note">Fuel is purchased per flight at the current market price. Routine maintenance is reserved in each flight’s costs. At 35% condition, aircraft automatically enter a 2-hour service. No manual fuel shopping or repeated departure clicks.</p></section><section class="panel panel-body"><span class="eyebrow">SERVICE REPUTATION</span><div class="money-large">${Math.floor(state.reputation)} <span class="muted" style="font-size:18px">/ 100</span></div><p class="note">Successful flights slowly increase your reputation. It never decays simply because you’re away. Invest in cabin training to lift your reputation ceiling to 100.</p></section></div><div class="card-grid">${UPGRADES.map(u=>`<article class="panel item-card"><div class="card-top"><div class="quest-icon">${icon(u.icon)}</div><span class="tag ${state.upgrades.includes(u.id)?'':'muted-tag'}">${state.upgrades.includes(u.id)?'Active':'Fleet-wide benefit'}</span></div><h3>${u.name}</h3><p style="margin-top:12px;min-height:63px">${u.desc}</p><div class="divider"></div><div class="mono">${money(u.cost)}</div><button class="card-action ${state.upgrades.includes(u.id)?'':'primary'}" data-action="upgrade-detail" data-id="${u.id}" ${state.upgrades.includes(u.id)?'disabled':''}>${state.upgrades.includes(u.id)?'Improvement complete':'Invest in your airline'}</button></article>`).join('')}</div>`;}
function renderContent(){const el=$('#content');if(!el)return;const open=new Set([...el.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent)),scroll=el.querySelector('.fleet-carousel')?.scrollLeft||0,active=document.activeElement;let focus=null;if(active&&el.contains(active)){if(active.id)focus='#'+CSS.escape(active.id);else{const attrs=[...active.attributes].filter(a=>a.name.startsWith('data-'));if(attrs.length)focus=attrs.map(a=>'['+a.name+'="'+CSS.escape(a.value)+'"]').join('');}}el.innerHTML=({overview,routes,fleet,airports,rivals,objectives,finances,operations,timeline,events:worldEventsView,notifications:notificationsView})[view]();for(const d of el.querySelectorAll('details'))d.open=open.has(d.querySelector('summary')?.textContent);const carousel=el.querySelector('.fleet-carousel');if(carousel)carousel.scrollLeft=scroll;if(view==='overview'||view==='routes')drawMap();if(focus)el.querySelector(focus)?.focus({preventScroll:true});lastRender=Date.now();}
function navigate(v){view=v;search='';shell();window.scrollTo({top:0,behavior:'instant'});}
function openModal(title,body,footer='',eyebrow='AEROVALE AIRLINE OPERATIONS'){const d=$('#dialog');d.innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><button class="ghost" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}<div class="modal-error" id="modal-error" role="alert"></div></div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();}
function closeModal(){$('#dialog').close();dialogType='';}
function buyPlaneModal(id){const m=E.model(id),price=E.aircraftPrice(state,id),status=E.modelStatus(state,m),available=status!=='upcoming'&&state.routes.length>=m.unlock;dialogType='purchase-plane';openModal(m.name,`${planeArt(m,true)}<p>${m.type}. Generation ${m.generation} · ${m.variant}. ${status==='upcoming'?'Introduced on game day '+(m.releaseDay+1)+'.':status==='legacy'?'Legacy market: discounted used aircraft.':'In production.'} ${m.fictionalVariant?'Fictional game technology variant.':''}</p><div class="data-grid"><div><small>Standard capacity</small><strong>${m.seats} seats</strong></div><div><small>Maximum range</small><strong>${num(m.range)} km</strong></div><div><small>Cruise speed</small><strong>${m.speed} km/h</strong></div><div><small>Fuel per kilometre</small><strong>${m.burn} units</strong></div></div><div class="breakdown"><div class="ledger-row"><span>Buy outright</span><span>${money(price)}</span></div><div class="ledger-row"><span>Or pay a lease deposit</span><span>${money(price*.14)}</span></div><div class="ledger-row"><span>Lease rent per game day</span><span>${money(price*.018)}</span></div></div><p class="note">Aircraft start at up to 70% resale value; age and obsolescence reduce it over time. Returning a leased aircraft refunds half its deposit. Lease rent continues while idle or paused in the hangar; pausing the whole simulation stops all costs.</p><p class="note" style="margin-top:15px">Available cash: <strong>${money(state.cash)}</strong></p>`,`<button data-action="goal-pin" data-id="${id}">${E.careerState(state).goal===id?'Aircraft goal pinned':'Set as aircraft goal'}</button><button data-action="buy-plane" data-id="${id}" data-lease="true" ${!available||state.cash<price*.14?'disabled':''}>Lease · ${money(price*.14,true)}</button><button class="primary" data-action="buy-plane" data-id="${id}" ${!available||state.cash<price?'disabled':''}>Buy · ${money(price,true)}</button>`,'AIRCRAFT ACQUISITION');}
function routeModal(a,b){const r=state.routes.find(x=>x.id===E.key(a,b)),chosen=ownedAircraftFor(a,b)||{model:E.releasedPlanes(state).find(p=>p.range>=E.distance(a,b))?.id||'a359'},e=E.economics(state,r||{a,b,fare:1},chosen),connected=E.connected(state).includes(a)||E.connected(state).includes(b),inRange=!!ownedAircraftFor(a,b),price=E.licensePrice(a,b),left=E.remainingLicenses(state,a,b);dialogType='route';openModal(`${a} <span class="muted">↔</span> ${b}`,`${airportArt(E.ap(b),'detail')}${r?routeAssignmentControls(r,'modal'):''}<p>${esc(E.ap(a).city)}, ${esc(E.ap(a).country)} → ${esc(E.ap(b).city)}, ${esc(E.ap(b).country)}</p><div class="data-grid"><div><small>Route distance</small><strong>${num(e.km)} km</strong></div><div><small>Round-trip time</small><strong>${hours(e.duration)}</strong></div><div><small>Daily market demand</small><strong>${num(E.routeDemand(state,a,b))} passengers</strong></div><div><small>Available airline licenses</small><strong>${left} of ${E.ROUTE_LICENSE_LIMIT}</strong></div></div>${r?masteryStrip(r):''}${routeSupply(a,b)}${eventImpactLine(a,b)}<label for="forecast-plane">Profit forecast with</label><select id="forecast-plane" data-a="${a}" data-b="${b}">${E.releasedPlanes(state).filter(p=>p.range>=e.km).map(p=>`<option value="${p.id}" ${p.id===chosen.model?'selected':''}>${p.name} · ${p.seats} seats</option>`).join('')}</select><div id="route-forecast">${forecast(e)}</div>${r?`<div class="form-field"><label for="fare">Ticket price: <strong id="fare-label">${Math.round(r.fare*100)}%</strong> of market fare</label><input id="fare" type="range" min="70" max="160" step="5" value="${Math.round(r.fare*100)}" style="width:100%" data-a="${a}" data-b="${b}"><div class="range-line"><span>Value · 70%</span><span>Premium · 160%</span></div></div><p class="note">Higher prices reduce seat occupancy. Changes affect the next departure, never a flight already in progress.</p>`:`<p class="note">${!left?'This connection is sold out. All '+E.ROUTE_LICENSE_LIMIT+' licenses are permanently owned; no more can be purchased.':'One-time license purchase. No expiration or renewal fees. Limited to '+E.ROUTE_LICENSE_LIMIT+' licenses shared by all airlines.'} ${!connected?'Connect one of these airports to your network first.':!inRange?'You need to acquire an aircraft with enough range before buying this route.':''}</p>`}`,r?`<button data-action="close">Close</button>${left?`<button data-action="buy-route" data-a="${a}" data-b="${b}" ${state.cash<price?'disabled':''}>Buy another license · ${money(price,true)}</button>`:''}<button class="primary" data-action="save-fare" data-id="${r.id}">Save ticket price</button>`:`<button data-action="close">Keep exploring</button><button class="primary" data-action="buy-route" data-a="${a}" data-b="${b}" ${!left||!connected||!inRange||state.cash<price?'disabled':''}>${!left?'Sold out · no licenses left':'Secure route · '+money(price,true)}</button>`,'ROUTE INTELLIGENCE');}
function forecast(e){return `<div class="breakdown"><div class="ledger-row"><span>Ticket revenue · ${e.pax} passengers</span><span>${money(e.revenue)}</span></div><div class="ledger-row"><span>Fuel</span><span>−${money(e.fuel)}</span></div><div class="ledger-row"><span>Crew & ground handling</span><span>−${money(e.crew)}</span></div><div class="ledger-row"><span>Maintenance reserve</span><span>−${money(e.maintenance)}</span></div><div class="ledger-row"><span>Airport fees</span><span>−${money(e.fees)}</span></div><div class="ledger-row"><span>Profit per round trip</span><span class="${e.profit>=0?'positive':'negative'}">${money(e.profit)}</span></div></div><p class="note">${pct(e.load)} occupancy · ${money(e.ticket)} per one-way ticket. Forecast includes competition and current market conditions; excludes lease rent and loan interest.</p>`;}
function planeModal(id){const p=state.planes.find(p=>p.id===id),m=E.model(p.model);dialogType='plane';activePlaneModalId=id;activePlaneFlying=!!p.flight;const busy=!!p.flight;openModal(`${p.id} · ${m.name}`,`${planeArt(m,true)}<p>${p.leased?'Leased':'Owned'} · ${num(m.range)} km range · ${Math.round(p.condition)}% condition · ${Math.max(0,E.gameDay(state)-(p.acquiredDay||0))} days old · ${E.modelStatus(state,m)} model</p>${busy?`<div class="notice space-top">Currently flying ${p.flight.route}. Returns in <span id="modal-arrival">${hours(p.flight.duration-p.progress)}</span>. Pause departures now; edit the rotation after this round trip lands.</div>`:''}<div class="settings-row"><div><h3>Automatic departures</h3><p>Fly this rotation repeatedly, including while you’re away.</p></div><button class="small ${p.auto?'primary':''}" data-action="toggle-auto" data-id="${id}">${p.auto?'On · pause':'Off · resume'}</button></div><div class="form-field"><label for="cabin">Cabin configuration</label><select id="cabin" ${busy?'disabled':''}><option value="standard" ${p.cabin==='standard'?'selected':''}>Balanced · ${m.seats} standard seats</option><option value="dense" ${p.cabin==='dense'?'selected':''}>High density · ${Math.floor(m.seats*1.14)} seats · lower comfort</option><option value="premium" ${p.cabin==='premium'?'selected':''}>Premium · ${Math.floor(m.seats*(E.careerState(state).perks.premium>=2?.8:.73))} seats · higher ticket yield</option></select></div><h3>Automatic round-trip rotation</h3><p class="note">Select up to 6 routes sharing one base. Each returns to base before the next departs. Each license supports one aircraft. Buy another available license to fly additional aircraft on the same connection.</p><div class="route-list space-top">${state.routes.filter(r=>E.distance(r.a,r.b)<=m.range).map(r=>{const assigned=state.planes.filter(x=>x.id!==id&&x.schedule.includes(r.id)),other=assigned.length>=E.routeLicenseCount(r)?assigned[0]:null;return `<label class="checkbox-row"><input type="checkbox" name="rotation" value="${r.id}" ${p.schedule.includes(r.id)?'checked':''} ${busy||other?'disabled':''}><div><strong>${r.a} ↔ ${r.b}</strong><small>${other?'Assigned to '+other.id:E.ap(r.a).city+' – '+E.ap(r.b).city+' · '+num(E.distance(r.a,r.b))+' km'}</small></div></label>`}).join('')||'<p class="note">No suitable routes yet. Buy a route within this aircraft’s range.</p>'}</div><p class="note" style="margin-top:15px">Current base: ${p.base}. Moving to a different shared base charges a one-time ferry cost based on distance and fuel consumption.</p><div class="divider"></div><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="small" data-action="service" data-id="${id}" ${busy?'disabled':''}>Preventive service · ${money(m.price*.01,true)}</button><button class="small" data-action="replacement-detail" data-id="${id}" ${busy?'disabled':''}>Compare & replace</button><button class="small danger" data-action="sell-detail" data-id="${id}" ${busy?'disabled':''}>${p.leased?'Return lease':'Sell aircraft'}</button></div>`,`<button data-action="close">Close</button><button class="primary" data-action="save-rotation" data-id="${id}" ${busy?'disabled':''}>Save & start rotation</button>`,'FLEET OPERATIONS');}
const sharePercent=n=>(n*100).toFixed(1).replace(/\.0$/,'')+'%';
function airportDevelopmentBadge(id){const stage=E.airportStage(state,id),d=E.airportDevelopment(state,id);return `<div class="airport-development-badge"><div><strong>${stage.name}</strong><span>${stage.levels} / 9 developments</span></div><div class="airport-development-mini">${E.AIRPORT_DEVELOPMENTS.map(path=>`<span title="${path.name}: level ${d[path.id]} of 3">${icon(path.icon)}${Array.from({length:3},(_,i)=>`<i class="${i<d[path.id]?'built':''}"></i>`).join('')}</span>`).join('')}</div></div>`;}
function airportBlueprint(id){const d=E.airportDevelopment(state,id),stage=E.airportStage(state,id);return `<div class="airport-blueprint"><div><span class="eyebrow">${id} · DEVELOPMENT PLAN</span><strong>${stage.name}</strong></div><svg viewBox="0 0 620 160" role="img" aria-label="Airport development: terminal level ${d.terminal}, retail level ${d.retail}, ground services level ${d.ground}, out of three each"><defs><pattern id="airport-plan-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#9cbded" stroke-opacity=".07"/></pattern></defs><rect width="620" height="160" fill="url(#airport-plan-grid)"/><rect x="20" y="105" width="580" height="27" rx="3" fill="#263f62" stroke="#54759d"/><path d="M30 119H590" stroke="#9fbbdd" stroke-dasharray="12 10"/><path d="M40 109v18m5-18v18m5-18v18M570 109v18m5-18v18m5-18v18" stroke="#b9cce4"/><path d="M95 105V81M310 105V81M501 105V81" stroke="#c5a466" stroke-width="2"/><rect x="42" y="48" width="106" height="33" rx="4" fill="#245ba4" stroke="#6aabff"/>${[0,1,2].map(i=>`<rect x="${45+i*35}" y="${d.terminal>i?25:34}" width="29" height="${d.terminal>i?23:14}" rx="2" fill="${d.terminal>i?'#72b2ff':'#102848'}" stroke="#72b2ff" stroke-dasharray="${d.terminal>i?'0':'3 3'}"/>`).join('')}<path d="M55 61h80M55 69h80" stroke="#9dc9ff" stroke-width="2"/><rect x="250" y="61" width="118" height="20" rx="3" fill="#665331" stroke="#cba25e"/>${[0,1,2].map(i=>`<g opacity="${d.retail>i?'1':'.35'}"><rect x="${255+i*38}" y="35" width="31" height="26" rx="2" fill="${d.retail>i?'#d5a65a':'#142c48'}" stroke="#ebc98f"/><path d="M${261+i*38} 40h19v6h-19z" fill="#ffe2ae" opacity=".7"/></g>`).join('')}<path d="M489 78V42h24v36" fill="#4c4a80" stroke="#a69add"/><path d="M482 41l7-15h24l7 15Z" fill="#8f86c5" stroke="#c0b5f1"/>${[0,1,2].map(i=>`<g opacity="${d.ground>i?'1':'.3'}"><rect x="${466+i*26}" y="79" width="21" height="12" rx="3" fill="${d.ground>i?'#b6a8e9':'#19324e'}" stroke="#b6a8e9"/><circle cx="${471+i*26}" cy="92" r="2" fill="#cbbff1"/><circle cx="${482+i*26}" cy="92" r="2" fill="#cbbff1"/></g>`).join('')}<text x="96" y="152" text-anchor="middle">TERMINAL ${d.terminal}/3</text><text x="310" y="152" text-anchor="middle">RETAIL ${d.retail}/3</text><text x="501" y="152" text-anchor="middle">GROUND ${d.ground}/3</text></svg></div>`;}
function airportDevelopmentPanel(id){const d=E.airportDevelopment(state,id);return `<section class="airport-development-panel">${airportBlueprint(id)}<div class="airport-benefit-totals"><span><strong>+${d.terminal*20}%</strong> independent traffic</span><span><strong>${sharePercent(E.airportShare(state,id))}</strong> revenue share</span><span><strong>−${d.ground*8}%</strong> ground time here</span></div><div class="section-label"><h3>Invest in this airport</h3><span class="note">${money(state.cash,true)} available</span></div><div class="airport-upgrade-list">${E.AIRPORT_DEVELOPMENTS.map(path=>{const rank=d[path.id],preview=E.airportUpgradePreview(state,id,path.id),delta=preview?preview.nextIncome-preview.currentIncome:0;return `<article class="airport-upgrade-row"><span class="airport-upgrade-icon ${path.id}">${icon(path.icon)}</span><div><div class="airport-upgrade-title"><h4>${path.name}</h4><span>LV ${rank} / 3</span></div><p>${path.benefit}</p>${preview?`<div class="airport-upgrade-preview"><span>Airport income / day</span><strong>${money(preview.currentIncome,true)} → ${money(preview.nextIncome,true)}</strong><small>${delta>=0?'+':''}${money(delta)} / day${path.id==='ground'?' · airline savings additional':''}</small></div><button class="primary" data-action="upgrade-airport" data-id="${id}" data-kind="${path.id}" ${state.cash<preview.cost?'disabled':''}>Upgrade to level ${preview.level} · ${money(preview.cost,true)}</button>`:`<div class="airport-upgrade-complete">${icon('check')} Fully developed · Permanent benefit</div>`}</div></article>`;}).join('')}</div><p class="note">Upgrades finish immediately and stay with the airport. Traffic and turnaround improvements help every carrier using it. Flights already airborne retain their original forecast. The five-license limit per connection stays the same.</p></section>`;}
function applyAirportUpgrade(id,kind){let upgraded=false;const body=$('.modal-body'),position=body?.scrollTop||0;act(()=>{E.upgradeAirport(state,id,kind);upgraded=true;},'Airport upgraded. Your development is permanent.',false);if(upgraded){airportModal(id);const next=$('.modal-body');if(next)next.scrollTop=position;}}
function airportModal(id){
 const a=E.ap(id),owned=state.airports.includes(id),ready=E.airportOpen(state,id)&&E.connected(state).includes(id),share=E.airportShare(state,id),income=E.airportDaily(state,id),baseline=E.airportBaselineIncome(state,id),value=E.airportAssetValue(state,id);
 dialogType='airport';openModal(`${a.id} · ${esc(a.city)}`,`${airportArt(a,'detail')}<p>${esc(a.country)} · ${a.region}${!E.airportOpen(state,id)?' · Opens on day '+(a.opensDay+1):''}</p><div class="data-grid"><div><small>${owned?'Airport asset value':'Acquisition price'}</small><strong>${money(owned?value:a.price)}</strong></div><div><small>Forecast income / day</small><strong class="positive">${money(income)}</strong></div></div>${owned?airportDevelopmentPanel(id):'<div class="notice space-top">Ownership unlocks 9 permanent developments: expand terminals, build a retail district and improve ground services.</div>'}<div class="breakdown"><div class="ledger-row"><span>Your share of airline revenue</span><strong>${sharePercent(share)}</strong></div><div class="ledger-row"><span>Independent carriers / day</span><span>${money(baseline)}</span></div><div class="ledger-row"><span>Your airline & active rivals / day</span><span>${money(income-baseline)}</span></div><div class="ledger-row"><span>${owned?'Development invested':'Estimated acquisition payback'}</span><span>${owned?money(E.airportDevelopment(state,id).invested):Math.ceil(a.price/income)+' game days'}</span></div></div><p class="note">Income arrives automatically. Independent carrier traffic is simulated from airport size. Your own and rival flights contribute when they land. Development forecasts show current market conditions; future traffic can change.</p>${!ready?'<div class="notice space-top">First connect this airport to your airline’s route network to unlock acquisition.</div>':''}`,`<button data-action="close">Close</button>${!owned?`<button class="primary" data-action="buy-airport" data-id="${id}" ${!ready||state.cash<a.price?'disabled':''}>Acquire airport · ${money(a.price,true)}</button>`:'<span class="chip">'+E.airportStage(state,id).name+'</span>'}`,owned?'AIRPORT DEVELOPMENT':'AIRPORT OWNERSHIP');
}

function settings(){dialogType='settings';openModal('Your airline. Your pace.',`<div class="form-field"><label for="airline-name">Airline name</label><input id="airline-name" maxlength="40" value="${esc(state.name)}"></div><div class="form-field"><label for="airline-color">Airline accent color</label><select id="airline-color">${[['#4b84ff','Aerovale blue'],['#67caff','Sky blue'],['#a6c9ef','Glacier blue'],['#efc48a','Golden hour'],['#d4b0ec','Orchid']].map(([v,n])=>`<option value="${v}" ${v===state.color?'selected':''}>${n}</option>`).join('')}</select></div><div class="divider"></div><h3>Your saved game</h3><p class="note">Progress is stored in this browser on this device. Export a backup to move to another device or keep a recovery copy. The hosted game and local preview have separate saves.</p><div style="display:flex;gap:10px;margin:18px 0"><button data-action="export">Export backup</button><button data-action="import">Import backup</button><input type="file" id="save-file" accept="application/json,.json" hidden></div><p class="note">While away, your scheduled flights and rivals continue at normal speed for up to 7 game days. At 1×, one real second equals 4 game minutes. Pausing the simulation stops away progress and costs.</p><div class="divider"></div><button class="small danger" data-action="reset-detail">Start a new airline</button>`,`<button data-action="close">Close</button><button class="primary" data-action="save-settings">Save changes</button>`,'GAME & SAVES');}
function help(){dialogType='help';openModal('Captain’s handbook',`<div class="help-content"><p>Start with $480,000 and a home base at Salt Lake City. Build a profitable airline, grow your network, and eventually own the airports it flies through.</p><h3>Your first five minutes</h3><ol class="note"><li>Open <strong>Fleet & hangar → Aircraft market</strong>. Buy an ATR 42 for $220,000.</li><li>Claim your first $30,000 objective reward.</li><li>In <strong>Route network → Explore routes</strong>, secure SLC–DEN. Inspect its profit forecast before buying.</li><li>On the SLC–DEN route card, choose an aircraft and tap <strong>Assign &amp; fly</strong>.</li><li>Watch your first flight return. Increase speed to 5× or 20× whenever you want.</li></ol><h3>A world that evolves</h3><p>Begin with 40 airports and 9 aircraft models. Twenty airports open every 10 game days until 600 are available. New airframes arrive through day 105; Eco, Express and Stretch generations follow every 60 days. By day 285, all 400 models and variants have appeared. These technology derivatives and release dates are fictional game design.</p><p>Models enter the legacy market after 100 days, with a 45% used discount. Aging increases maintenance costs and reduces resale value. Compare replacements from any idle aircraft; trade-ins preserve its routes and rotation. Aircraft specifications are game-balanced approximations.</p><h3>Make thoughtful trade-offs</h3><p>Longer routes unlock bigger earnings, but need more expensive aircraft. Range is one way; each scheduled flight is a round trip. Standard, dense and premium cabins change capacity and ticket yield. Raising fares lowers demand.</p><p>Daily forecasts include fuel, crew, maintenance and fees. Leased aircraft also pay rent while idle. Compare profit per game day, not just revenue per flight.</p><h3>Compete without losing your progress</h3><p>Every connection has ${E.ROUTE_LICENSE_LIMIT} airline licenses shared by you and all rivals. You can own several; each supports one aircraft. Both directions share that supply. Rivals forecast their intentions before buying one. Your licenses never expire. Once all licenses are owned, the connection is sold out and cannot be purchased, even at a higher price.</p><h3>Build an airport portfolio</h3><p>Connect an airport before acquiring it. You’ll earn 3% of its simulated carrier revenue, rising to 4% with retail partnerships. Own and rival flights add income when they land; independent carriers provide baseline traffic.</p><h3>Automation & time</h3><p>Rotations can include up to 6 round-trip routes sharing a common base. Pause automatic departures and wait for the current flight to finish before editing. Fuel purchasing and routine maintenance are automatic.</p><p>1× means 4 game minutes per real second. Free 5× and 20× controls are always available. Away progress runs at 1× for up to 7 game days. Pausing stops the whole world.</p><h3>Airport development</h3><p>Open Airports → Manage &amp; upgrade on an owned airport. Terminal, retail and ground-service developments have three levels each. Terminals grow independent-carrier income and passenger demand, retail raises your revenue share, and ground services shorten the ground-time portion of future round trips. Improvements help all carriers using that airport. Upgrades cost cash, complete immediately and remain in your saved airline. Their investment is included in airport asset value. Route license supply stays at five.</p><h3>Contracts & airline development</h3><p>Choose two contracts in Career. Only profitable flights that depart after you accept count; contracts and unclaimed rewards never expire. Each commission earns cash and a strategy credit. Spend credits on permanent regional, premium or efficiency specializations. Benefits start with future departures. Route mastery adds 2%, 4% or 6% ticket revenue after 10, 40 or 120 completed round trips, including your past flights. Pin an aircraft from its details to track your next big purchase on the flight deck.</p><h3>Inspired by player feedback</h3><p>Built around the aircraft collection, business decisions, route maps and steady progression players enjoy, with free fast-forward, repeatable rotations, explicit costs, permanent reputation, local backups, and replayable guidance.</p><p><a href="https://steamcommunity.com/app/1641650/reviews/?browsefilter=toprated" target="_blank" rel="noopener">Steam player reviews</a> · <a href="https://apps.apple.com/us/app/airline-manager-2026/id1487669805" target="_blank" rel="noopener">App Store reviews</a> · <a href="https://www.reddit.com/r/AirlineManager4/comments/1eacgui/" target="_blank" rel="noopener">Fleet scheduling discussion</a></p><p class="note">Aerovale is an original single-player game, not affiliated with Airline Manager or aircraft manufacturers. Real airport locations, intentionally scaled fictional economics. Airport expansion data: public-domain <a href="https://ourairports.com/data/" target="_blank" rel="noopener">OurAirports</a>. Map: public-domain Natural Earth. Original aircraft artwork generated for Aerovale.</p></div>`,`<button class="primary" data-action="close">Ready for takeoff</button>`,'ALWAYS HERE WHEN YOU NEED IT');}
function credit(){dialogType='credit';openModal('A little room to grow.',`<p>Use business credit to fund profitable expansion. Interest is charged continuously at 0.2% per game day.</p><div class="data-grid"><div><small>Outstanding debt</small><strong>${money(state.debt)}</strong></div><div><small>Current credit limit</small><strong>${money(Math.max(150000,Math.min(5000000,E.netWorth(state)*.5)))}</strong></div></div><label for="credit-amount">Amount (multiples of $1,000)</label><input id="credit-amount" type="number" min="1000" step="1000" value="50000"><p class="note space-top">Cash available: ${money(state.cash)}. No application or early repayment fees.</p>`,`<button data-action="repay" ${state.debt<=0?'disabled':''}>Repay credit</button><button class="primary" data-action="borrow">Draw credit</button>`,'FINANCING');}
function exportSave(){save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='aerovale-day-'+(Math.floor(state.minute/1440)+1)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Your save backup has been exported.');}
function act(fn,message,close=true){try{fn();save();if(close)closeModal();shell();if(message)toast(message);}catch(e){if($('#dialog').open&&$('#modal-error'))$('#modal-error').textContent=e.message;else toast(e.message);}}
function projection(lon,lat){return [(lon+180)*3,(85-lat)*3];}
function point(id){const a=E.ap(id);return projection(a.lon,a.lat);}
function curve(a,b){const [x,y]=point(a),[xx,yy]=point(b),mx=(x+xx)/2,my=(y+yy)/2-Math.min(90,Math.abs(xx-x)*.24+14);return {path:`M${x},${y} Q${mx},${my} ${xx},${yy}`,x,y,xx,yy,mx,my};}
function drawMap(){const map=$('#network-map');if(!map)return;const focus=map.contains(document.activeElement)?[...document.activeElement.attributes].filter(a=>a.name.startsWith('data-')).map(a=>'['+a.name+'="'+CSS.escape(a.value)+'"]').join(''):'';const conn=E.connected(state),bounds=mapBounds(),[bx,by,bw,bh]=bounds,w=bw/mapZoom,h=bh/mapZoom,box=[bx+(bw-w)/2+mapPan.x,by+(bh-h)/2+mapPan.y,w,h],unit=Math.max(w/Math.max(300,map.clientWidth),h/Math.max(250,map.clientHeight)),r=Math.max(1,unit*4),selected=mapSelected&&E.ap(mapSelected);const path=(a,b,cls)=>`<path class="route-line ${cls}" d="${curve(a,b).path}"/>`;const routes=(mapRivals?state.rivals.flatMap(ai=>ai.routes.map(r=>path(r.a,r.b,'rival'))).join(''):'')+state.routes.map(r=>`<g data-action="route-detail" data-a="${r.a}" data-b="${r.b}" class="map-route" role="button" tabindex="0" aria-label="Manage route ${r.a} to ${r.b}"><path class="route-hit" d="${curve(r.a,r.b).path}"/>${path(r.a,r.b,'owned')}</g>`).join('');const previews=selected&&selected.id!==routeOrigin?path(routeOrigin,selected.id,'preview'):!state.routes.length?['DEN','LAS','PHX','LAX','SEA'].map(id=>path(state.home,id,'suggested')).join(''):'';const flights=state.planes.filter(p=>p.flight).map(p=>{const route=state.routes.find(r=>r.id===p.flight.route);if(!route)return '';const c=curve(route.a,route.b);let progress=E.clamp(p.progress/p.flight.duration,0,1),out=progress<.5,t=out?progress*2:(1-progress)*2;const x=(1-t)**2*c.x+2*(1-t)*t*c.mx+t*t*c.xx,y=(1-t)**2*c.y+2*(1-t)*t*c.my+t*t*c.yy,dx=2*(1-t)*(c.mx-c.x)+2*t*(c.xx-c.mx),dy=2*(1-t)*(c.my-c.y)+2*t*(c.yy-c.my),angle=Math.atan2(dy,dx)*180/Math.PI+(out?45:225);return `<g class="flight-marker" data-action="plane-detail" data-id="${p.id}" role="button" tabindex="0" aria-label="Flight ${p.id}" transform="translate(${x},${y})"><circle r="${10*unit}" fill="#102952" fill-opacity=".9"/><g transform="rotate(${angle}) scale(${unit*.65}) translate(-12,-12)"><path d="${paths.plane}" fill="#fabb56" stroke="#ffdc91" stroke-width="1.5"/></g><title>${p.id} · ${route.id}</title></g>`;}).join('');const aps=E.openAirports(state).filter(a=>mapAirports||conn.includes(a.id)||a.id===mapSelected).map(a=>{const [x,y]=point(a.id),home=a.id===state.home,owned=conn.includes(a.id),sel=a.id===mapSelected,label=owned||sel||mapZoom>=2||(mapRegion==='america'?['DEN','SEA','LAX','DFW','ORD','JFK','MIA','MEX','LAS','PHX'].includes(a.id):['LHR','GRU','JNB','DXB','SIN','HND','SYD'].includes(a.id));if(x<box[0]-15||x>box[0]+w+15||y<box[1]-15||y>box[1]+h+15)return '';return `<g class="map-airport ${home?'home':''} ${owned?'connected':''} ${sel?'selected-map':''}" data-airport="${a.id}" role="button" tabindex="0" aria-label="${esc(a.city)} ${a.id}" transform="translate(${x},${y})"><title>${esc(a.city)} (${a.id})</title><circle class="hit" r="${Math.max(7*unit,2)}"/>${home||sel?`<circle class="airport-halo" r="${r*2.3}"/>`:''}<circle class="dot" r="${owned||sel?r:r*.6}"/>${label?`<text style="font-size:${Math.max(2,10*unit)}px" x="${6*unit}" y="${-7*unit}">${a.id}</text>`:''}</g>`;}).join('');map.innerHTML=`<svg id="world-svg" viewBox="${box.join(' ')}" preserveAspectRatio="xMidYMid meet" role="group" aria-label="Interactive airline route map"><defs><radialGradient id="sea"><stop stop-color="#162e50"/><stop offset="1" stop-color="#09162d"/></radialGradient></defs><rect x="-1500" y="-1000" width="4000" height="2500" fill="url(#sea)"/>${Array.from({length:25},(_,i)=>`<path class="gridline" d="M${i*45},-500V1500"/>`).join('')}${Array.from({length:13},(_,i)=>`<path class="gridline" d="M-1000,${i*45}H2500"/>`).join('')}${geoPaths}<text x="186" y="72" class="map-label">NORTH AMERICA</text><text x="287" y="345" class="map-label">SOUTH AMERICA</text><text x="540" y="227" class="map-label">AFRICA</text><text x="770" y="111" class="map-label">ASIA</text><text x="928" y="374" class="map-label">AUSTRALIA</text>${routes}${previews}${aps}${flights}</svg><div class="map-regions">${[['america','Americas'],['europe','Europe'],['asia','Asia'],['world','World']].map(([v,n])=>`<button data-action="map-region" data-region="${v}" class="${mapRegion===v?'active':''}">${n}</button>`).join('')}</div><div class="map-toolbar"><button data-action="map-in" aria-label="Zoom in">+</button><button data-action="map-out" aria-label="Zoom out">−</button></div><div class="map-legend"><span><i class="legend-dot"></i>Your routes</span><button class="${mapRivals?'on':''}" data-action="map-rivals" aria-pressed="${mapRivals}"><i class="legend-dot rival"></i>Rivals</button><button class="${mapAirports?'on':''}" data-action="map-airports" aria-pressed="${mapAirports}">Airports ${mapAirports?'on':'off'}</button></div>${selected?mapAirportPreview(selected):`<div class="map-caption">${view==='routes'?'PLANNING FROM '+routeOrigin:!state.routes.length?'Your first connection is waiting.':'Every connection is part of your story.'}<small>Tap an airport · Drag to pan · + to zoom</small></div>`}`;if(focus)map.querySelector(focus)?.focus({preventScroll:true});}
function mapBounds(){return ({america:[110,35,260,205],europe:[475,45,200,155],asia:[650,5,370,285],world:[0,0,1080,500]})[mapRegion]||[0,0,1080,500];}
function selectMapAirport(id){mapSelected=id;drawMap();}
function mapAirportPreview(a){const origin=routeOrigin===a.id?E.connected(state).find(id=>id!==a.id)||state.home:routeOrigin,owned=state.routes.find(r=>r.id===E.key(origin,a.id)),same=origin===a.id;return `<div class="map-destination"><button class="map-dismiss" data-action="map-select-close" aria-label="Close airport preview">×</button><span class="eyebrow">${esc(a.country)}</span><h3>${a.id} <span>${esc(a.city)}</span></h3><p>${same?'Your home base':origin+' → '+a.id+' · '+num(E.distance(origin,a.id))+' km'}</p>${!same?`<p class="map-license-count">${owned?E.routeLicenseCount(owned)+' yours · ':''}${E.remainingLicenses(state,origin,a.id)?E.remainingLicenses(state,origin,a.id)+' of '+E.ROUTE_LICENSE_LIMIT+' licenses available':'Sold out · all '+E.ROUTE_LICENSE_LIMIT+' licenses owned'}</p>`:''}<div>${!same?`<button class="primary small" data-action="route-detail" data-a="${origin}" data-b="${a.id}">${owned?'Manage route':!E.remainingLicenses(state,origin,a.id)?'View sold-out route':'Plan route'} ${icon('arrow')}</button>`:''}<button class="small" data-action="airport-detail" data-id="${a.id}">Airport details</button>${E.connected(state).includes(a.id)&&a.id!==routeOrigin?`<button class="small" data-action="map-origin" data-id="${a.id}">Use as origin</button>`:''}</div></div>`;}
function fitNetwork(){const ids=E.connected(state),pts=ids.map(point);if(ids.length<2){mapRegion='america';mapZoom=1;mapPan={x:0,y:0};drawMap();return;}const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),left=Math.min(...xs)-30,right=Math.max(...xs)+30,top=Math.min(...ys)-35,bottom=Math.max(...ys)+35;mapRegion='world';mapZoom=E.clamp(Math.min(1080/(right-left),500/(bottom-top)),1,8);mapPan={x:(left+right)/2-540,y:(top+bottom)/2-250};drawMap();}
function updateForecast(){const s=$('#forecast-plane');if(!s)return;const a=s.dataset.a,b=s.dataset.b,r=state.routes.find(r=>r.id===E.key(a,b)),fare=$('#fare')?Number($('#fare').value)/100:r?.fare||1;$('#route-forecast').innerHTML=forecast(E.economics(state,{a,b,fare},{model:s.value}));if($('#fare-label'))$('#fare-label').textContent=Math.round(fare*100)+'%';}
function careerProgress(value,target,label){return `<div class="progress" role="progressbar" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="${target}" aria-valuenow="${Math.min(value,target)}"><span style="width:${Math.min(100,value/target*100)}%"></span></div>`;}
function contractTitle(c){return c.type==='spotlight'?c.routeId+' · Destination spotlight':E.contractType(c.type).title;}
function contractRule(c){return `${c.target} ${c.target===1?E.contractType(c.type).verb.replace(/trips$/,'trip'):E.contractType(c.type).verb}${c.type==='shuttle'?' · ≤ 2,000 km':c.type==='fullhouse'?' · ≥ 80% full':c.type==='longhaul'?' · ≥ 3,000 km':c.type==='efficient'?' · ≤ 4.5 fuel / 100 seat-km':''}`;}
function contractPlan(c){
 const seen=r=>c.type!=='variety'||[r.a,r.b].some(id=>!c.seen.includes(id));
 const qualifies=(p,r,e)=>seen(r)&&E.contractQualifies(c,r,{...e,careerFlight:{departedAt:state.minute+1,cabin:p.cabin,fuelPerSeat:E.model(p.model).burn/E.model(p.model).seats}});
 for(const p of state.planes){for(const rid of p.schedule){const r=state.routes.find(r=>r.id===rid);if(r&&qualifies(p,r,E.economics(state,r,p)))return {route:r,plane:p,text:p.auto?`${p.id} is scheduled for qualifying flights.`:`Resume ${p.id} to make progress.`,label:'Manage working route'};}}
 for(const r of state.routes.slice(0,120)){const p=state.planes.find(p=>E.model(p.model).range>=E.distance(r.a,r.b)&&qualifies(p,r,E.economics(state,r,p)));if(p)return {route:r,plane:p,text:`${p.id} can qualify on ${r.a}–${r.b}. Assign it to start.`,label:'Set up this route'};}
 return {text:!state.planes.length?'Start with an aircraft, then secure its first route.':E.contractType(c.type).hint,label:!state.planes.length?'Choose an aircraft':c.type==='premium'?'Configure a premium cabin':'Plan qualifying routes'};
}
function contractCard(c,active=false,compact=false){
 const def=E.contractType(c.type),ready=c.completedAt!==null,plan=active&&!ready?contractPlan(c):null,capacity=E.careerState(state).active.length>=2;
 return `<article class="panel contract-card ${ready?'contract-ready':''} ${compact?'compact':''}"><div class="contract-header"><span class="contract-symbol">${icon(ready?'check':def.icon)}</span><div><span class="eyebrow">${active?ready?'COMMISSION READY':'ACTIVE CONTRACT':esc(def.client)}</span><h3>${esc(contractTitle(c))}</h3></div>${active?`<strong class="contract-fraction">${c.progress}<small> / ${c.target}</small></strong>`:''}</div><p class="contract-rule">${esc(contractRule(c))}</p>${active?careerProgress(c.progress,c.target,contractTitle(c)):''}${!compact?`<p class="contract-hint">${esc(ready?'Your flights fulfilled the brief. Collect your commission and choose your next challenge.':plan?.text||def.hint)}</p>`:''}<div class="commission-reward"><span>${icon('wallet')} ${money(c.reward,true)}</span><span>${icon('star')} 1 strategy credit</span></div><div class="contract-actions"><button class="${!active||ready?'primary':''}" data-action="${active?ready?'contract-claim':'contract-work':'contract-accept'}" data-id="${c.id}" ${!active&&capacity?'disabled':''}>${active?ready?'Collect commission':plan.label:capacity?'Two contracts active':'Accept contract'} ${icon('arrow')}</button>${active&&!ready&&!compact?`<button class="ghost small" data-action="contract-release-detail" data-id="${c.id}" aria-label="Release ${esc(contractTitle(c))}">Release</button>`:''}</div></article>`;
}
function aircraftGoalCard(){
 const id=E.careerState(state).goal,m=id&&E.model(id);
 if(!m)return `<section class="panel aircraft-goal empty-goal"><span class="eyebrow">THE NEXT BIG THING</span><h3>What will you fly next?</h3><p>Pick a dream aircraft. Keep its price, unlocks, and your savings in sight.</p><div class="goal-silhouette">${icon('plane')}</div><button data-action="market">Choose an aircraft goal ${icon('arrow')}</button></section>`;
 const price=E.aircraftPrice(state,id),available=E.modelStatus(state,m)!=='upcoming'&&state.routes.length>=m.unlock,owned=state.planes.some(p=>p.model===id),short=Math.max(0,price-state.cash);
 return `<section class="panel aircraft-goal">${planeArt(m)}<div class="goal-body"><div class="goal-label"><span class="eyebrow">YOUR AIRCRAFT GOAL</span><button class="ghost small" data-action="goal-clear" aria-label="Clear aircraft goal">×</button></div><h3>${esc(m.name)}</h3>${owned?'<p class="goal-ready">In your fleet. Dream achieved.</p>':careerProgress(Math.max(0,state.cash),price,'Savings for '+m.name)+`<div class="goal-funds"><strong>${money(Math.max(0,state.cash),true)}</strong><span>of ${money(price,true)} to buy</span></div><p class="note">${E.modelStatus(state,m)==='upcoming'?'Introduced on day '+(m.releaseDay+1)+'. ':''}${state.routes.length<m.unlock?'Needs '+m.unlock+' owned routes. ':''}${short?money(short,true)+' left to save.':'Purchase price saved.'}</p>`}<button class="${available&&!short&&!owned?'primary':''}" data-action="${owned?'market':'buy-plane-detail'}" data-id="${id}">${owned?'Choose your next goal':available&&!short?'Ready to acquire':'View aircraft'} ${icon('arrow')}</button></div></section>`;
}
function nextMove(){
 const c=E.initializeCareer(state),credits=E.strategyCredits(state),active=[...c.active].sort((a,b)=>Number(b.completedAt!==null)-Number(a.completedAt!==null)),totalRanks=Object.values(c.perks).reduce((n,x)=>n+x,0);
 return `<section class="next-move"><div class="section-label"><div><span class="eyebrow">BUILD YOUR KIND OF AIRLINE</span><h2>Your next move</h2></div><button class="ghost small" data-view="objectives">Career desk ${icon('arrow')}</button></div><div class="next-move-grid"><div class="next-contracts">${active.length?active.map(x=>contractCard(x,true,true)).join(''):`<div class="career-invitation panel"><div class="career-invitation-art">${icon('trophy')}<span>01 / CHOOSE YOUR NEXT CHALLENGE</span></div><div><h3>A commission with your name on it.</h3><p>Win contracts. Earn strategy credits. Build a regional powerhouse, a premium airline, or a lean global fleet.</p><button class="primary" data-view="objectives">Choose a contract ${icon('arrow')}</button></div></div>`}<button class="development-nudge" data-action="career-tab" data-id="development"><span>${icon('star')} ${credits?`${credits} strategy credit${credits===1?'':'s'} to spend`:`${totalRanks} / 9 airline developments`}</span><strong>${credits?'Develop your advantage':'Preview your next advantage'} ${icon('arrow')}</strong></button></div>${aircraftGoalCard()}</div></section>`;
}
function masteryStrip(r){const m=E.routeMastery(r);return `<div class="mastery-strip"><div><span>${icon('star')} ${m.name}</span><strong>${m.level?'+'+Math.round(m.bonus*100)+'% revenue':m.flights+' trips'}</strong></div>${m.next?careerProgress(m.flights-m.previous,m.next-m.previous,r.id+' route mastery')+`<small>${m.next-m.flights} round trips to ${['','Established','Trusted','Signature route'][m.level+1]} · +${(m.level+1)*2}% ticket revenue</small>`:'<small>120+ round trips. Your signature connection.</small>'}</div>`;}
function developmentView(){const c=E.careerState(state),credits=E.strategyCredits(state);return `<div class="career-explainer"><div><h2>Decide what your airline does best.</h2><p>Each contract earns one strategy credit. Develop any branch; you can eventually complete all three. Every benefit is permanent and applies to future departures.</p></div><span class="credit-balance">${credits}<small>STRATEGY CREDITS</small></span></div>${c.founderCredits?`<p class="founder-note">${icon('star')} Your existing flight history earned ${c.founderCredits} founding credit${c.founderCredits===1?'':'s'}. Your airline starts here with its progress intact.</p>`:''}<div class="specialization-grid">${E.SPECIALIZATIONS.map(path=>{const rank=c.perks[path.id];return `<article class="panel specialization ${path.id}"><div class="specialization-emblem">${icon(path.icon)}<span>${rank}/3</span></div><span class="eyebrow">AIRLINE SPECIALIZATION</span><h3>${path.name}</h3><p>${path.description}</p><ol>${path.steps.map((step,i)=>`<li class="${rank>i?'developed':rank===i?'next-development':''}"><span>${rank>i?icon('check'):i+1}</span><div><strong>${step.name}</strong><p>${step.effect}</p><small>${rank>i?'PERMANENT BENEFIT':(i+1)+' STRATEGY CREDIT'+(i?'S':'')}</small></div></li>`).join('')}</ol><button class="${rank<3&&credits>=rank+1?'primary':''}" data-action="develop-detail" data-id="${path.id}" ${rank===3?'disabled':''}>${rank===3?'Fully developed':`Develop ${path.steps[rank].name} · ${rank+1} credit${rank?'s':''}`}</button></article>`;}).join('')}</div><div class="section-label"><div><span class="eyebrow">THE NETWORK YOU HAVE BUILT</span><h2>Route mastery</h2></div><span class="note">Old flights count, too</span></div><p class="note mastery-explainer">10 / 40 / 120 completed round trips earn +2% / +4% / +6% ticket revenue on that connection. Keep building a favorite route, or expand into a new market.</p><div class="mastery-grid">${[...state.routes].sort((a,b)=>E.routeMastery(b).level-E.routeMastery(a).level||b.flights-a.flights).slice(0,12).map(r=>`<article class="panel mastery-card">${airportArt(E.ap(r.b))}<div><h3>${r.a} ↔ ${r.b}</h3>${masteryStrip(r)}<button class="small" data-action="route-detail" data-a="${r.a}" data-b="${r.b}">Manage route ${icon('arrow')}</button></div></article>`).join('')||'<div class="panel empty"><h3>Your first signature route starts with one flight.</h3><button data-view="routes">Build your network</button></div>'}</div>${state.routes.length>12?'<p class="note space-top">Showing your 12 most established connections. Every route’s mastery is also visible in Route network.</p>':''}`;}
function contractsView(){const c=E.initializeCareer(state);return `<div class="career-explainer"><div><h2>Choose the work worth flying for.</h2><p>Run up to two contracts at once. Only profitable flights departing after acceptance count. Contracts stay open while you’re away; rewards wait until you collect them.</p></div><span class="credit-balance">${c.completed}<small>CONTRACTS WON</small></span></div>${c.active.length?`<div class="section-label"><h2>Your active contracts</h2><span class="eyebrow">${c.active.length} / 2 ACTIVE</span></div><div class="active-contract-grid">${c.active.map(x=>contractCard(x,true)).join('')}</div>`:''}<div class="section-label"><h2>On the contract board</h2><span class="note">Cash + permanent progress</span></div><div class="contract-grid">${c.offers.map(x=>contractCard(x)).join('')}</div>${c.history.length?`<details class="panel contract-history"><summary>${c.completed} contract${c.completed===1?'':'s'} won · View your recent commissions</summary>${c.history.slice(0,8).map(x=>`<div class="ledger-row"><span>${esc(contractTitle(x))}<small>DAY ${Math.floor(x.claimedAt/1440)+1}</small></span><strong>${money(x.reward,true)} + 1 credit</strong></div>`).join('')}</details>`:''}`;}
function objectives(){const milestoneReady=QUESTS.filter(q=>!state.claims.includes(q.id)&&E.questValue(state,q)>=q.target).length;return `<div class="career-tabs" role="group" aria-label="Career sections">${[['contracts','Contracts'],['development','Develop airline'],['milestones','Milestones']].map(([id,label])=>`<button data-action="career-tab" data-id="${id}" class="${careerTab===id?'primary':''}" aria-pressed="${careerTab===id}">${label}${id==='milestones'&&milestoneReady?` <span class="tab-count">${milestoneReady}</span>`:''}${id==='development'&&E.strategyCredits(state)?` <span class="tab-count">${E.strategyCredits(state)}</span>`:''}</button>`).join('')}</div>${careerTab==='development'?developmentView():careerTab==='milestones'?milestonesView():contractsView()}`;}
function workContract(id){const c=E.careerState(state).active.find(x=>x.id===id);if(!c)return;const plan=contractPlan(c);if(plan.route){routeModal(plan.route.a,plan.route.b);return;}if(!state.planes.length){fleetTab='market';navigate('fleet');return;}if(c.type==='premium'){planeModal(state.planes[0].id);return;}routesTab='explore';routeOrigin=state.home;routePage=0;search='';rangeFilter='all';navigate('routes');toast(E.contractType(c.type).hint);}
function collectCommission(id){let result;act(()=>{result=E.claimContract(state,id);},'');if(!result)return;openModal('Commission earned.',`<div class="commission-celebration"><div class="celebration-seal">${icon('trophy')}</div><span class="eyebrow">${esc(contractTitle(result))}</span><div class="money-large">+${money(result.reward)}</div><p>+1 strategy credit</p></div><p>Your flights paid off. Turn this credit into a permanent advantage, or choose another contract for your fleet.</p>`,`<button data-action="career-tab" data-id="contracts">Choose another contract</button><button class="primary" data-action="career-tab" data-id="development">Develop your airline ${icon('arrow')}</button>`,'A NEW CHAPTER FOR YOUR AIRLINE');}
function developmentModal(id){const path=E.SPECIALIZATIONS.find(x=>x.id===id),rank=E.careerState(state).perks[id];if(!path||rank>=3)return;const step=path.steps[rank];openModal(step.name,`<div class="development-modal-emblem">${icon(path.icon)}</div><p class="eyebrow">${path.name} · DEVELOPMENT ${rank+1} OF 3</p><h3 class="space-top">${step.effect}</h3><p class="space-top">This permanent benefit starts with future departures. Flights already in the air keep their original economics.</p><p class="note space-top">Costs ${rank+1} strategy credit${rank?'s':''}. Available: ${E.strategyCredits(state)}. Credits can be earned again through more contracts.</p>`,`<button data-action="close">Keep planning</button><button class="primary" data-action="develop" data-id="${id}" ${E.strategyCredits(state)<rank+1?'disabled':''}>Develop for ${rank+1} credit${rank?'s':''}</button>`,'CHOOSE YOUR ADVANTAGE');}

document.addEventListener('click',e=>{if(!leader&&e.target.closest('button,[data-airport]')){takeControl();lastTick=Date.now();}const nav=e.target.closest('[data-view]');if(nav){closeModal();navigate(nav.dataset.view);return;}const speed=e.target.closest('[data-speed]');if(speed){state.speed=Number(speed.dataset.speed);lastTick=Date.now();save();shell();return;}const ft=e.target.closest('[data-fleet-tab]');if(ft){fleetTab=ft.dataset.fleetTab;renderContent();return;}const rt=e.target.closest('[data-route-tab]');if(rt){routesTab=rt.dataset.routeTab;search='';routePage=0;renderContent();return;}const airport=e.target.closest('[data-airport]');if(airport){selectMapAirport(airport.dataset.airport);return;}const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,a=b.dataset.a,d=b.dataset.b;switch(b.dataset.action){
case 'close':closeModal();break;
case 'career-tab':careerTab=['contracts','development','milestones'].includes(id)?id:'contracts';closeModal();navigate('objectives');break;
case 'contract-accept':act(()=>E.acceptContract(state,id),'Contract accepted. Your next qualifying departures count.');break;
case 'contract-claim':collectCommission(id);break;
case 'contract-work':workContract(id);break;
case 'contract-release-detail':openModal('Release this contract?',`<p>The current contract progress will be lost. There is no cash penalty, and your aircraft, routes and earned strategy credits stay with you.</p>`,`<button data-action="close">Keep contract</button><button data-action="contract-release" data-id="${id}">Release contract</button>`,'CHANGE YOUR PLAN');break;
case 'contract-release':act(()=>E.abandonContract(state,id),'Contract released. Choose another direction.');break;
case 'develop-detail':developmentModal(id);break;
case 'develop':act(()=>E.developSpecialization(state,id),'Airline developed. Your next departures gain the new benefit.');break;
case 'goal-pin':act(()=>E.setAircraftGoal(state,id),'Aircraft goal pinned to your flight deck.');break;
case 'goal-clear':act(()=>E.setAircraftGoal(state,null),'Aircraft goal cleared.');break;
case 'notifications-read-all':E.markNotificationsRead(state);save();shell();break;
case 'notification-open':notificationDetail(id);break;
case 'notification-filter':noticeFilter=id;notificationPage=0;renderContent();break;
case 'notification-page':notificationPage=Math.max(0,Number(id));renderContent();window.scrollTo({top:0,behavior:'instant'});break;
case 'event-explore':exploreEvent(id);break;
case 'future-planes':planeStage='upcoming';catalogPage=0;fleetTab='market';navigate('fleet');break;
case 'page':{const page=Number(b.dataset.page);if(b.dataset.kind==='planes')catalogPage=page;else if(b.dataset.kind==='airports')airportPage=page;else routePage=page;renderContent();window.scrollTo({top:0,behavior:'instant'});break;}
case 'replacement-detail':replacementModal(id);break;
case 'replace-plane':act(()=>E.replacePlane(state,id,$('#replacement-model').value),'Aircraft replaced. Your rotation is preserved.');break;
case 'market':catalogPage=0;fleetTab='market';navigate('fleet');break;
case 'help':help();break;
case 'nav-more':openModal('Your airline desk',`<div class="route-list">${navs.filter(n=>['airports','rivals','finances','operations','events','timeline'].includes(n[0])).map(([id,i,label])=>`<button data-view="${id}" style="text-align:left;padding:16px">${icon(i)} &nbsp; ${label}</button>`).join('')}<button data-action="settings" style="text-align:left;padding:16px">${icon('settings')} &nbsp; Game & saves</button><button data-action="help" style="text-align:left;padding:16px">${icon('help')} &nbsp; Captain’s handbook</button></div>`);break;
case 'settings':settings();break;
case 'export':exportSave();break;
case 'import':$('#save-file').click();break;
case 'save-settings':act(()=>{const n=$('#airline-name').value.trim();if(!n)throw Error('Give your airline a name.');state.name=n.slice(0,40);state.color=$('#airline-color').value;},'Your airline details are updated.');break;
case 'reset-detail':openModal('Start a new airline?',`<p>This replaces your current airline on this device. Export a backup first if you’d like to keep it.</p>`,`<button data-action="export">Export current save</button><button class="danger" data-action="reset">Start fresh with $480,000</button>`,'NEW CAMPAIGN');break;
case 'reset':state=E.createGame();fleetTab='owned';routesTab='explore';routeOrigin='SLC';act(()=>{},'A new adventure begins.');navigate('overview');break;
case 'buy-plane-detail':buyPlaneModal(id);break;
case 'buy-plane':act(()=>E.buyPlane(state,id,b.dataset.lease==='true'),'Aircraft acquired. Now secure a route and schedule its rotation.');fleetTab='owned';navigate('fleet');break;
case 'plane-detail':planeModal(id);break;
case 'toggle-auto':{const p=state.planes.find(p=>p.id===id);p.auto=!p.auto;save();planeModal(id);renderContent();break;}
case 'save-rotation':act(()=>E.schedulePlane(state,id,[...document.querySelectorAll('input[name=rotation]:checked')].map(x=>x.value),$('#cabin').value),'Rotation saved. Your crew will depart automatically.');break;
case 'service':act(()=>E.servicePlane(state,id),'Preventive service scheduled. Back in 90 game minutes.');break;
case 'sell-detail':{const p=state.planes.find(x=>x.id===id),value=E.resaleValue(state,p);openModal(p.leased?'Return this aircraft?':'Sell this aircraft?',`<p>${p.id} will leave your fleet. Its routes remain yours and can be assigned to another aircraft.</p><div class="money-large">${money(value)}</div><p class="note">${p.leased?'Half of the original deposit is refunded. Daily lease rent stops.':'Resale price reflects the aircraft’s age and current market status.'}</p>`,`<button data-action="close">Keep aircraft</button><button class="primary" data-action="sell" data-id="${id}">${p.leased?'Return lease':'Confirm sale'}</button>`);break;}
case 'sell':act(()=>E.sellPlane(state,id),'Aircraft removed from your fleet.');break;
case 'assign-route':{const select=b.closest('.route-assignment')?.querySelector('select');act(()=>E.assignPlaneToRoute(state,id,select?.value),'Aircraft assigned. Automatic departures are on.');break;}
case 'route-detail':routeModal(a,d);break;
case 'buy-route':act(()=>E.buyRoute(state,a,d),'License secured. Assign an aircraft to its new capacity.');break;
case 'save-fare':act(()=>E.setFare(state,id,Number($('#fare').value)/100),'Ticket price updated for future departures.');break;
case 'airport-detail':airportModal(id);break;
case 'buy-airport':{let bought=false;act(()=>{E.buyAirport(state,id);bought=true;},'Airport acquired. You can now develop it.');if(bought)airportModal(id);break;}
case 'upgrade-airport':applyAirportUpgrade(id,b.dataset.kind);break;
case 'claim':act(()=>E.claimQuest(state,id),'Objective complete. Reward added to your funds.');break;
case 'quest-go':{const q=QUESTS.find(x=>x.id===id);if(q.type==='planes')fleetTab='market';if(q.type==='routes'||q.type==='destinations'||q.type==='longest'||q.type==='continents')routesTab='explore';navigate(q.view);break;}
case 'upgrade-detail':{const u=UPGRADES.find(x=>x.id===id);openModal(u.name,`<p>${u.desc}</p><div class="money-large">${money(u.cost)}</div><p class="note">A permanent improvement across your entire airline.</p>`,`<button data-action="close">Keep planning</button><button class="primary" data-action="buy-upgrade" data-id="${id}" ${state.cash<u.cost?'disabled':''}>Complete investment</button>`,'AIRLINE DEVELOPMENT');break;}
case 'buy-upgrade':act(()=>E.buyUpgrade(state,id),'Improvement complete. Your airline is stronger.');break;
case 'credit':credit();break;
case 'borrow':act(()=>E.borrow(state,Number($('#credit-amount').value)),'Credit drawn. The funds are now available.');break;
case 'repay':act(()=>E.repay(state,Number($('#credit-amount').value)),'Credit repayment complete.');break;
case 'rescue':act(()=>E.rescue(state),'Recovery grant added to your funds.');break;
case 'map-region':mapRegion=b.dataset.region||'world';mapZoom=1;mapPan={x:0,y:0};mapSelected=null;drawMap();break;
case 'map-origin':routeOrigin=id;mapSelected=null;renderContent();toast('Route origin set to '+id+'. Select your next destination.');break;
case 'map-rivals':mapRivals=!mapRivals;drawMap();break;
case 'map-airports':mapAirports=!mapAirports;drawMap();break;
case 'map-fit':fitNetwork();break;
case 'map-select-close':mapSelected=null;drawMap();break;
case 'map-in':mapZoom=Math.min(8,mapZoom*1.5);drawMap();break;
case 'map-out':mapZoom=Math.max(1,mapZoom/1.5);mapPan={x:0,y:0};drawMap();break;
}});
document.addEventListener('input',e=>{if(e.target.id==='route-search'){routePage=0;search=e.target.value;const pos=e.target.selectionStart;renderContent();$('#route-search').focus();$('#route-search').setSelectionRange(pos,pos);}if(e.target.id==='fare')updateForecast();if(['plane-search','airport-search'].includes(e.target.id)){const id=e.target.id,pos=e.target.selectionStart;if(id==='plane-search'){planeSearch=e.target.value;catalogPage=0;}else{airportSearch=e.target.value;airportPage=0;}renderContent();$('#'+id).focus();$('#'+id).setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{if(e.target.dataset.routePlane){const rid=e.target.dataset.routePlane,box=e.target.closest('.route-assignment'),scope=box.dataset.assignmentScope;routePlaneChoices.set(rid,e.target.value);(box.closest('.route-assignment-group')||box).outerHTML=routeAssignmentControls(state.routes.find(r=>r.id===rid),scope);$('#assign-'+scope+'-'+rid)?.focus({preventScroll:true});return;}if(e.target.id==='plane-stage'){planeStage=e.target.value;catalogPage=0;renderContent();}if(e.target.id==='plane-type'){planeType=e.target.value;catalogPage=0;renderContent();}if(e.target.id==='airport-stage'){airportStage=e.target.value;airportPage=0;renderContent();}if(e.target.id==='airport-region'){airportRegion=e.target.value;airportPage=0;renderContent();}if(e.target.id==='replacement-model')replacementComparison($('#replacement-model').dataset.plane,e.target.value);if(e.target.id==='route-origin'){routeOrigin=e.target.value;routePage=0;renderContent();}if(e.target.id==='route-sort'){sort=e.target.value;routePage=0;renderContent();}if(e.target.id==='range-filter'){rangeFilter=e.target.value;routePage=0;renderContent();}if(e.target.id==='forecast-plane')updateForecast();if(e.target.id==='save-file'){const f=e.target.files?.[0];if(!f)return;try{if(f.size>1500000)throw Error('This file is too large for an Aerovale save.');const imported=E.validateSave(JSON.parse(await f.text()));window.pendingImport=imported;openModal('Restore this airline?',`<p>Replace your current game with <strong>${esc(imported.name)}</strong>?</p><div class="data-grid"><div><small>Available funds</small><strong>${money(imported.cash)}</strong></div><div><small>Route network</small><strong>${imported.routes.length} routes</strong></div></div><p class="note">Export your current game first if you want to keep both. Restoring does not award additional away earnings.</p>`,`<button data-action="close">Cancel</button><button id="confirm-import" class="primary">Restore saved game</button>`,'IMPORT BACKUP');$('#confirm-import').addEventListener('click',()=>{state=window.pendingImport;delete window.pendingImport;lastTick=Date.now();act(()=>{},'Your airline has been restored.');});}catch(err){toast('Could not import: '+err.message);}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-action]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));return;}const airport=e.target.closest('[data-airport]');if(airport&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selectMapAirport(airport.dataset.airport);}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
let dragging=null;document.addEventListener('pointerdown',e=>{if(e.target.closest('#world-svg')&&!e.target.closest('[data-airport]')){dragging={x:e.clientX,y:e.clientY,pan:{...mapPan}};}});document.addEventListener('pointermove',e=>{if(!dragging)return;const rect=$('#network-map')?.getBoundingClientRect();if(!rect)return;const bounds=mapBounds(),unit=Math.max(bounds[2]/rect.width,bounds[3]/rect.height)/mapZoom;mapPan={x:E.clamp(dragging.pan.x-(e.clientX-dragging.x)*unit,-350,350),y:E.clamp(dragging.pan.y-(e.clientY-dragging.y)*unit,-200,200)};drawMap();});document.addEventListener('pointerup',()=>dragging=null);document.addEventListener('pointercancel',()=>dragging=null);
function tick(){const now=Date.now(),secs=(now-lastTick)/1000;lastTick=now;if(leader&&state.speed&&state.started){E.advance(state,Math.min(10080,secs*4*(secs>60?1:state.speed)));}if($('#dialog').open&&dialogType==='plane'&&activePlaneModalId){const p=state.planes.find(p=>p.id===activePlaneModalId);if(p&&activePlaneFlying!==!!p.flight)planeModal(activePlaneModalId);else if(p?.flight&&$('#modal-arrival'))$('#modal-arrival').textContent=hours(Math.max(0,p.flight.duration-p.progress));}if($('#game-date'))$('#game-date').textContent=dateString();if($('#game-time'))$('#game-time').textContent=`${timeString()} · DAY ${Math.floor(state.minute/1440)+1}`;const typing=['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName);if(state.speed&&state.started&&now-lastRender>2500&&now>interactionUntil&&!typing&&!dragging&&!$('#dialog').open)renderContent();if(state.speed&&state.started&&(view==='overview'||view==='routes')&&now>interactionUntil&&!dragging&&!$('#dialog').open)drawMap();refreshNotifications();if(now-state.lastSave>10000)save();}
shell();save();
fetch('assets/world.json').then(r=>{if(!r.ok)throw Error('Map unavailable');return r.json();}).then(geo=>{geoPaths=geo.features.map(f=>{const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;return polys.map(poly=>`<path class="land" d="${poly.map(r=>r.map((v,i)=>`${i?'L':'M'}${projection(v[0],v[1]).map(n=>n.toFixed(1)).join(',')}`).join('')+'Z').join('')}"/>`).join('')}).join('');drawMap();}).catch(()=>toast('Map background could not load. Route controls are still available.'));
setInterval(tick,1000);window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else tick();});
window.addEventListener('storage',e=>{if(e.key===OWNER&&e.newValue){try{const owner=JSON.parse(e.newValue);if(owner.id!==sessionId)leader=false;}catch{}return;}if(e.key!==STORE||!e.newValue||leader)return;try{const other=E.validateSave(JSON.parse(e.newValue));if(other.lastSave>state.lastSave){state=other;lastTick=Date.now();if(!$('#dialog').open)shell();}}catch{}});
if(offlineReport)setTimeout(()=>openModal('Welcome back, captain.',`<p>Your airline kept moving while you were away.</p><div class="data-grid"><div><small>Completed round trips</small><strong>${num(offlineReport.flights)}</strong></div><div><small>Net cash earned</small><strong class="${offlineReport.cash>=0?'positive':'negative'}">${money(offlineReport.cash)}</strong></div></div><p class="note">${offlineReport.contracts?offlineReport.contracts+' contract'+(offlineReport.contracts===1?'':'s')+' completed. Your commissions are ready to collect. ':''}${offlineReport.mastery?offlineReport.mastery+' route mastery level'+(offlineReport.mastery===1?'':'s')+' earned. ':''}Simulated ${hours(offlineReport.minutes)} at normal speed, capped at 7 game days. Your reputation is just as you left it—or better.</p>`,`<button data-action="close">Back to the skies</button><button class="primary" data-view="objectives">Review your contracts</button>`,'WHILE YOU WERE AWAY'),500);
if(storageError)setTimeout(()=>toast('Browser storage is unavailable or the previous save was invalid. Export backups in Game & saves.'),800);
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'read_airline_state',title:'Read airline state',description:'Read current finances, fleet, owned routes, airport portfolio and rival plans.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({name:state.name,cash:Math.round(state.cash),day:Math.floor(state.minute/1440)+1,planes:state.planes.map(p=>({id:p.id,model:p.model,schedule:p.schedule,auto:p.auto})),routes:state.routes.map(r=>({id:r.id,a:r.a,b:r.b,licenses:E.routeLicenseCount(r),remaining:E.remainingLicenses(state,r.a,r.b)})),airports:state.airports,airportDevelopments:state.airports.map(id=>({id,...E.airportDevelopment(state,id),stage:E.airportStage(state,id).name,share:E.airportShare(state,id),income:E.airportDaily(state,id)})),rivalPlan:E.rivalPlans(state)[0]||null,rivalPlans:E.rivalPlans(state),rivals:state.rivals.map(ai=>({id:ai.id,licenses:ai.routes.length,cash:Math.round(ai.cash),status:ai.expansionStatus||'scouting',nextReview:ai.nextExpansionAt??null})),career:{...E.careerState(state),credits:E.strategyCredits(state)},world:E.nextWorldEvent(state),events:{active:E.activeWorldEvents(state),upcoming:E.upcomingWorldEvents(state),newcomer:E.newcomerInfo(state)},notifications:(state.notifications||[]).map(n=>({id:n.id,kind:n.kind,title:n.title,read:n.read,items:n.items||[]}))})},{name:'open_aircraft_purchase',title:'Open aircraft purchase',description:'Stage an aircraft purchase by opening its detail dialog. Does not buy the aircraft.',inputSchema:{type:'object',properties:{model:{type:'string',description:'Aircraft catalog ID, such as atr42, q400, e175, or atr42-g2.'}},required:['model'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.model!=='string'||!E.model(input.model))throw Error('Unknown aircraft model.');buyPlaneModal(input.model);return {opened:true,model:input.model,purchased:false};}},{name:'set_simulation_speed',title:'Set simulation speed',description:'Pause or set the airline simulation to normal, 5x or 20x speed. Changes time progression for the whole world.',inputSchema:{type:'object',properties:{speed:{type:'number',enum:[0,1,5,20]}},required:['speed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||![0,1,5,20].includes(input.speed))throw Error('Choose speed 0, 1, 5 or 20.');takeControl();state.speed=input.speed;lastTick=Date.now();save();shell();return {speed:state.speed};}}];for(const t of tools){try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
registerTools();

function replacementModal(id){const p=state.planes.find(p=>p.id===id),current=E.model(p.model),maxRange=Math.max(0,...p.schedule.map(id=>{const r=state.routes.find(r=>r.id===id);return E.distance(r.a,r.b);})),options=E.releasedPlanes(state).filter(m=>m.id!==p.model&&m.range>=maxRange&&state.routes.length>=m.unlock).sort((a,b)=>Number(b.family===current.family)-Number(a.family===current.family)||b.generation-a.generation||a.price-b.price);if(!options.length){toast('No compatible replacement is available yet.');return;}openModal('A smarter next aircraft.',`<p>Replace ${p.id} · ${current.name}. Your routes, cabin and rotation are preserved. The replacement is purchased outright; any previous lease ends.</p><div class="form-field"><label for="replacement-model">Replacement model</label><select id="replacement-model" data-plane="${id}">${options.map(m=>`<option value="${m.id}">${esc(m.name)} · ${money(E.aircraftPrice(state,m.id),true)}</option>`).join('')}</select></div><div id="replacement-comparison"></div>`,`<button data-action="close">Keep current aircraft</button><button class="primary" data-action="replace-plane" data-id="${id}">Trade in & replace</button>`,'FLEET MODERNIZATION');replacementComparison(id,options[0].id);}
function replacementComparison(id,mid){const p=state.planes.find(p=>p.id===id),a=E.model(p.model),b=E.model(mid),trade=E.resaleValue(state,p),price=E.aircraftPrice(state,mid),old=E.rotationStats(state,p).daily,future=E.rotationStats(state,{...p,model:mid,leased:false,acquiredDay:E.gameDay(state),auto:true}).daily;$('#replacement-comparison').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Comparison</th><th>Current</th><th>Replacement</th></tr></thead><tbody>${[['Seats',a.seats,b.seats],['Speed',a.speed+' km/h',b.speed+' km/h'],['Range',num(a.range)+' km',num(b.range)+' km'],['Fuel / 100 seat-km',(a.burn/a.seats*100).toFixed(2),(b.burn/b.seats*100).toFixed(2)],['Rotation / day',money(old),money(future)]].map(([k,a,b])=>`<tr><td>${k}</td><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div><div class="breakdown"><div class="ledger-row"><span>Replacement purchase</span><span>${money(price)}</span></div><div class="ledger-row"><span>Current trade-in value</span><span>−${money(trade)}</span></div><div class="ledger-row"><span>Net cash required</span><strong>${money(price-trade)}</strong></div></div><p class="note">${b.description} Future profit assumes automatic departures resume. Larger aircraft can lose money if a route cannot fill their seats.</p>`;const button=$('[data-action="replace-plane"]');if(button)button.disabled=state.cash<price-trade;}

if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));

window.addEventListener('resize',()=>{if(!dragging)drawMap();});
